            ["tr.Names10.name"] = new[] { "Name keeper", "Знаток имён", "Есім білгірі", "Conocedor de nombres", "Sabe os nomes" },
            ["tr.Names10.desc"] = new[] { "Name the entity correctly 10 times.", "Верно назови сущность 10 раз.", "Тылсым күштің атын 10 рет дұрыс ата.", "Nombra correctamente a la entidad 10 veces.", "Diga o nome certo da entidade 10 vezes." },
            ["tr.Clean5.name"] = new[] { "Clean work", "Чистая работа", "Таза жұмыс", "Trabajo limpio", "Trabalho limpo" },
            ["tr.Clean5.desc"] = new[] { "5 nights without a single mistake.", "5 ночей без единой ошибки.", "Бірде-бір қатесіз 5 түн.", "5 noches sin un solo error.", "5 noites sem nenhum erro." },
            ["tr.Silent.name"] = new[] { "Not a sound", "Ни звука", "Үнсіз", "Ni un ruido", "Nem um som" },
            ["tr.Silent.desc"] = new[] { "Banish an entity without being heard once.", "Изгони сущность, ни разу не выдав себя шумом.", "Шуыңмен бір рет те білдірмей тылсым күшті қу.", "Expulsa una entidad sin que te oiga ni una vez.", "Expulse uma entidade sem ser ouvido nenhuma vez." },
            ["tr.Photo5.name"] = new[] { "Photographer", "Фотограф", "Фотограф", "Fotógrafo", "Fotógrafo" },
            ["tr.Photo5.desc"] = new[] { "Photograph 5 different entities.", "Сфотографируй 5 разных сущностей.", "5 түрлі тылсым күшті суретке түсір.", "Fotografía 5 entidades distintas.", "Fotografe 5 entidades diferentes." },
            ["tr.AllMet.name"] = new[] { "Bestiary", "Бестиарий", "Бестиарий", "Bestiario", "Bestiário" },
            ["tr.AllMet.desc"] = new[] { "Meet all 8 entities.", "Встреть все 8 сущностей.", "Барлық 8 тылсым күшпен кездес.", "Encuentra las 8 entidades.", "Encontre as 8 entidades." },
            ["tr.Night5.name"] = new[] { "Five nights", "Пять ночей", "Бес түн", "Cinco noches", "Cinco noites" },
            ["tr.Night5.desc"] = new[] { "Reach night 5 in one game.", "Дойди до 5-й ночи за одну игру.", "Бір ойында 5-түнге жет.", "Llega a la noche 5 en una partida.", "Chegue à noite 5 em uma partida." },
            ["tr.Night10.name"] = new[] { "Ten nights", "Десять ночей", "Он түн", "Diez noches", "Dez noites" },
