            ["tr.Stash10.name"] = new[] { "Scavenger", "Собиратель", "Жинаушы", "Rebuscador", "Catador" },
            ["tr.Stash10.desc"] = new[] { "Find 10 stashes.", "Найди 10 тайников.", "10 жасырын қорды тап.", "Encuentra 10 escondites.", "Encontre 10 esconderijos." },
            ["tr.Streak7.name"] = new[] { "Night shift", "Ночная смена", "Түнгі ауысым", "Turno de noche", "Turno da noite" },
            ["tr.Streak7.desc"] = new[] { "Solve the daily case 7 days in a row.", "Раскрой дело дня 7 дней подряд.", "Күн ісін 7 күн қатарынан шеш.", "Resuelve el caso del día 7 días seguidos.", "Resolva o caso do dia 7 dias seguidos." },
