            ["practice_hold"] = new[] { "Keep holding — the light is burning it…", "Держи — свет жжёт…", "Ұстай бер — жарық күйдіріп жатыр…", "Mantén — la luz la quema…", "Segure — a luz está queimando…" },
            ["practice_done"] = new[] {
                "Learned! {0} is ready for the night.",
