            ["h.Practice"] = new[] {
                "Not every gesture is learned yet. Practise them in the Journal → Items: there is no time to learn in the dark.",
                "Не все жесты изучены. Потренируйся в Дневнике → Предметы: в темноте учиться некогда.",
                "Барлық қимыл үйренілген жоқ. Күнделік → Заттар бөлімінде жаттық: қараңғыда үйренуге уақыт жоқ.",
                "Aún no has aprendido todos los gestos. Practícalos en Diario → Objetos: en la oscuridad no hay tiempo para aprender.",
                "Nem todos os gestos foram aprendidos. Treine no Diário → Itens: no escuro não dá tempo de aprender." },
            ["e.Lechuza.name"] = new[] { "La Lechuza", "Ла Лечуса", "Ла Лечуса", "La Lechuza", "La Lechuza" },
            ["e.Lechuza.origin"] = new[] { "Mexican and Texan folklore", "Фольклор Мексики и Техаса", "Мексика мен Техас фольклоры", "Folclore de México y Texas", "Folclore do México e do Texas" },
            ["e.Lechuza.lore"] = new[] {
                "A witch who sold her soul and takes the shape of a giant owl with a woman's face. At night she sits on the roof and cries like a newborn baby, so that someone will open the door. Grandmothers on the border said: throw salt at her, and tie seven knots in a rope — she cannot cross salt.",
                "Ведьма, продавшая душу, оборачивается огромной совой с женским лицом. Ночью садится на крышу и плачет, как новорождённый, — чтобы кто-нибудь открыл дверь. Бабушки на границе говорили: брось в неё соль и завяжи на верёвке семь узлов — соль она не переходит.",
                "Жанын сатқан мыстан әйел бетті алып үкіге айналады. Түнде шатырға қонып, жаңа туған нәрестедей жылайды — біреу есік ашсын деп. Шекарадағы әжелер айтатын: оған тұз лақтыр да, арқанға жеті түйін түй — ол тұздан аттай алмайды.",
                "Una bruja que vendió su alma y toma la forma de una lechuza gigante con cara de mujer. De noche se posa en el tejado y llora como un recién nacido, para que alguien abra la puerta. Las abuelas de la frontera decían: échale sal y haz siete nudos en una cuerda; la sal no la puede cruzar.",
                "Uma bruxa que vendeu a alma e toma a forma de uma coruja gigante com rosto de mulher. À noite pousa no telhado e chora como um recém-nascido, para que alguém abra a porta. As avós da fronteira diziam: jogue sal nela e dê sete nós numa corda — o sal ela não atravessa." },
            ["e.Lechuza.signs"] = new[] {
                "A baby crying where there is no baby; a whistle from above. She crawls across the ceiling and drops on you from above when she is close.",
                "Плач младенца там, где младенца нет; свист сверху. Ползёт по потолку и падает сверху, когда подберётся близко.",
                "Сәби жоқ жерде сәбидің жылауы; жоғарыдан ысқырық. Төбемен жорғалап, жақындағанда үстіңе құлайды.",
                "Llanto de bebé donde no hay ningún bebé; un silbido desde arriba. Se arrastra por el techo y cae sobre ti cuando está cerca.",
                "Choro de bebê onde não há bebê; um assobio lá de cima. Ela rasteja pelo teto e cai sobre você quando chega perto." },
            ["e.Lechuza.defense"] = new[] {
                "Salt. Look up and throw a handful at her.",
                "Соль. Подними взгляд и брось в неё горсть.",
                "Тұз. Жоғары қарап, оған бір уыс лақтыр.",
                "Sal. Mira hacia arriba y lánzale un puñado.",
                "Sal. Olhe para cima e jogue um punhado nela." },
            ["e.Lechuza.hint"] = new[] {
                "It's La Lechuza. Look up! She fears salt: look at her and swipe up.",
                "Это Ла Лечуса. Смотри наверх! Она боится соли: посмотри на неё и смахни пальцем вверх.",
                "Бұл — Ла Лечуса. Жоғары қара! Ол тұздан қорқады: оған қарап, саусақпен жоғары сырғыт.",
                "Es La Lechuza. ¡Mira arriba! Teme la sal: mírala y desliza hacia arriba.",
                "É La Lechuza. Olhe para cima! Ela teme sal: olhe para ela e deslize para cima." },
            ["e.Lechuza.lair"] = new[] {
                "Up high, under the ceiling — the way she perches on the roof.",
                "Высоко, под потолком — так она сидит на крыше.",
                "Жоғарыда, төбенің астында — ол шатырда осылай отырады.",
                "Arriba, bajo el techo: así se posa en el tejado.",
                "No alto, sob o teto — é assim que ela pousa no telhado." },
            ["e.Lechuza.tale"] = new[] {
                "In a village near the Rio Grande, a young mother heard a baby crying outside one night and went out with a lamp. On the fence sat an owl as big as a man. It turned its head, and she saw a woman's face — her own neighbour's. In the morning the neighbour had salt burns on her arms and would not meet anyone's eyes.",
                "В деревне у Рио-Гранде молодая мать ночью услышала за окном плач младенца и вышла с лампой. На заборе сидела сова ростом с человека. Она повернула голову — и женщина увидела человеческое лицо. Лицо своей соседки. Утром у соседки на руках были ожоги от соли, и она ни на кого не поднимала глаз.",
                "Рио-Гранде маңындағы ауылда жас ана түнде терезе сыртынан нәрестенің жылағанын естіп, шамды алып шықты. Шарбақта адам бойындай үкі отыр еді. Ол басын бұрды — әйел адамның бетін көрді. Өз көршісінің бетін. Таңертең көршісінің қолдарында тұздан күйген іздер болды, ол ешкімнің көзіне қарамады.",
                "En un pueblo cerca del río Bravo, una madre joven oyó de noche llorar a un bebé afuera y salió con una lámpara. En la cerca había una lechuza del tamaño de un hombre. Giró la cabeza, y la mujer vio un rostro humano: el de su vecina. Por la mañana la vecina tenía quemaduras de sal en los brazos y no miraba a nadie a los ojos.",
                "Numa aldeia perto do Rio Grande, uma jovem mãe ouviu à noite um bebê chorando lá fora e saiu com um lampião. Na cerca havia uma coruja do tamanho de um homem. Ela virou a cabeça, e a mulher viu um rosto humano: o da sua vizinha. De manhã a vizinha tinha queimaduras de sal nos braços e não olhava ninguém nos olhos." },
            ["e.Cucuy.name"] = new[] { "El Cucuy", "Эль Кукуй", "Эль Кукуй", "El Cucuy", "O Cuca-Coco" },
            ["e.Cucuy.origin"] = new[] {
                "Spanish and Latin American folklore",
                "Испанский и латиноамериканский фольклор",
                "Испан және Латын Америкасы фольклоры",
                "Folclore español y latinoamericano",
                "Folclore ibérico e latino-americano" },
            ["e.Cucuy.lore"] = new[] {
                "\"Duérmete niño, que viene el Coco…\" — the thing mothers sing about in the lullaby. It has no fixed shape: a lump of darkness with red eyes that lives under the bed and in the closet and takes children who will not sleep. It hates light: as long as the lamp is on, it does not come out.",
                "«Спи, дитя, а то придёт Коко…» — о нём поётся в колыбельной. Определённой формы у него нет: сгусток тьмы с красными глазами, что живёт под кроватью и в шкафу и забирает детей, которые не спят. Свет он ненавидит: пока горит лампа, он не выходит.",
                "«Ұйықта, балам, әйтпесе Коко келеді…» — бесік жырында ол туралы айтылады. Оның нақты пішіні жоқ: төсек астында және шкафта тұратын, ұйықтамайтын балаларды алып кететін қызыл көзді қараңғылық кесегі. Ол жарықты жек көреді: шам жанып тұрғанда шықпайды.",
                "«Duérmete niño, duérmete ya, que viene el Coco y te comerá…». No tiene forma fija: un bulto de oscuridad con ojos rojos que vive debajo de la cama y en el armario y se lleva a los niños que no duermen. Odia la luz: mientras la lámpara esté encendida, no sale.",
                "\"Dorme, neném, que a Cuca vem pegar…\" — é dele que fala a canção de ninar. Não tem forma certa: um bolo de escuridão com olhos vermelhos que vive debaixo da cama e no armário e leva as crianças que não dormem. Odeia a luz: enquanto a lâmpada estiver acesa, ele não sai." },
            ["e.Cucuy.signs"] = new[] {
                "Scratching under the bed, heavy breathing, a growl too low for a human. It creeps toward you along the floor in the dark — and freezes in the light.",
                "Скребётся под кроватью, тяжело дышит, рычит слишком низко для человека. Подползает к тебе по полу в темноте — и замирает на свету.",
                "Төсек астында тырналайды, ауыр дем алады, адамдыкінен тым жуан ырылдайды. Қараңғыда еденмен саған жорғалайды — жарықта қатып қалады.",
                "Araña debajo de la cama, respira pesado, gruñe demasiado grave para ser humano. Se arrastra hacia ti por el suelo en la oscuridad y se congela con la luz.",
                "Arranha debaixo da cama, respira pesado, rosna grave demais para ser gente. Rasteja até você pelo chão no escuro — e congela na luz." },
            ["e.Cucuy.defense"] = new[] {
                "The lantern. Keep the light on it until nothing is left.",
                "Фонарь. Держи на нём свет, пока от него ничего не останется.",
                "Шам. Одан ештеңе қалмағанша жарықты үстінен түсірме.",
                "La linterna. Mantén la luz sobre él hasta que no quede nada.",
                "A lanterna. Mantenha a luz nele até não sobrar nada." },
            ["e.Cucuy.hint"] = new[] {
                "It's El Cucuy. It fears light: hold your finger — the lantern — and keep it in the beam.",
                "Это Эль Кукуй. Он боится света: зажми палец — фонарь — и держи его в луче.",
                "Бұл — Эль Кукуй. Ол жарықтан қорқады: саусағыңды басып тұр — шам жанады — және оны сәуледе ұста.",
                "Es El Cucuy. Teme la luz: mantén el dedo pulsado (la linterna) y no lo saques del haz.",
                "É o Cuca-Coco. Ele teme luz: segure o dedo (a lanterna) e mantenha-o no feixe." },
            ["e.Cucuy.lair"] = new[] {
                "Low on the floor, in the darkest gap — under a bed, behind a closet door.",
                "Низко на полу, в самой тёмной щели — под кроватью, за дверцей шкафа.",
                "Еденде, ең қараңғы саңылауда — төсек астында, шкаф есігінің артында.",
                "Abajo, en el suelo, en el hueco más oscuro: debajo de una cama, detrás de la puerta del armario.",
                "Embaixo, no chão, na fresta mais escura — debaixo da cama, atrás da porta do armário." },
            ["e.Cucuy.tale"] = new[] {
                "In Spain they once made a turnip lantern with a carved face and set it in the window: let the Coco think someone was already watching. Mothers who forgot the lantern found the bed in the morning neatly made — and the child's shoes still under it, toes pointing toward the wall.",
                "В Испании когда-то вырезали из репы фонарь с лицом и ставили на окно: пусть Коко думает, что за домом уже смотрят. Матери, забывшие о фонаре, утром находили кровать аккуратно застеленной — а под ней детские туфли, носками к стене.",
                "Испанияда бір кездері шалқанан бет-әлпетті шам ойып, терезеге қоятын: Коко үйді біреу күзетіп тұр деп ойласын. Шамды ұмытқан аналар таңертең төсекті ұқыпты жиналған күйде табатын — ал астында баланың туфлиі, тұмсығы қабырғаға қараған.",
                "En España se tallaba una linterna con cara en un nabo y se ponía en la ventana: que el Coco creyera que ya alguien vigilaba. Las madres que olvidaban la linterna encontraban por la mañana la cama bien hecha y, debajo, los zapatos del niño con las puntas hacia la pared.",
                "Na Espanha, antigamente, esculpia-se uma lanterna com rosto num nabo e colocava-se na janela: que o Coco pensasse que alguém já vigiava a casa. As mães que esqueciam a lanterna encontravam de manhã a cama bem arrumada — e debaixo dela os sapatos da criança, com as pontas viradas para a parede." },
            ["e.Chupacabra.name"] = new[] { "Chupacabra", "Чупакабра", "Чупакабра", "Chupacabras", "Chupa-cabra" },
            ["e.Chupacabra.origin"] = new[] {
                "Puerto Rican and Mexican folklore",
                "Фольклор Пуэрто-Рико и Мексики",
                "Пуэрто-Рико мен Мексика фольклоры",
                "Folclore de Puerto Rico y México",
                "Folclore de Porto Rico e do México" },
            ["e.Chupacabra.lore"] = new[] {
                "\"The goat-sucker.\" A creature the size of a dog, with grey scaly skin, a row of spines down its back and huge red eyes. It drains animals of blood through three neat holes. Farmers say it only hunts in total darkness: floodlights in the yard kept it away better than any gun.",
                "«Сосущая коз». Тварь размером с собаку, с серой чешуйчатой кожей, гребнем шипов вдоль спины и огромными красными глазами. Выпивает кровь у скота через три аккуратные дырочки. Фермеры говорят: охотится только в полной темноте — прожектор во дворе отгонял её лучше любого ружья.",
                "«Ешкі сорғыш». Иттей үлкен, сұр қабыршақты терісі, арқасында тікенді жотасы және алып қызыл көздері бар мақұлық. Малдың қанын үш ұқыпты тесік арқылы сорып алады. Фермерлер айтады: тек қараңғы түнекте аулайды — аулада жанған прожектор оны кез келген мылтықтан жақсы қуатын.",
                "«La que chupa cabras». Una criatura del tamaño de un perro, de piel gris escamosa, una cresta de púas en el lomo y enormes ojos rojos. Desangra a los animales por tres agujeros limpios. Los granjeros dicen que solo caza en la oscuridad total: un reflector en el patio la alejaba mejor que cualquier escopeta.",
                "\"O chupador de cabras.\" Uma criatura do tamanho de um cachorro, de pele cinza escamosa, uma crista de espinhos nas costas e enormes olhos vermelhos. Suga o sangue dos animais por três furinhos certinhos. Os fazendeiros dizem que só caça no escuro total: um holofote no quintal a espantava melhor que qualquer espingarda." },
            ["e.Chupacabra.signs"] = new[] {
                "Chittering, a rattle of spines, a sharp smell of blood. It freezes — then lunges in jerks, faster than you can turn.",
                "Стрекот, треск шипов, резкий запах крови. Замирает — и бросается рывками, быстрее, чем успеваешь повернуться.",
                "Шықылдақ, тікендердің сылдыры, қанның өткір иісі. Қатып қалады да — сен бұрылып үлгергенше жұлқынып атылады.",
                "Chasquidos, un crujir de púas, un olor fuerte a sangre. Se queda quieta y embiste a tirones, más rápido de lo que puedes girarte.",
                "Estalidos, um chocalhar de espinhos, um cheiro forte de sangue. Fica parada — e avança aos trancos, mais rápido do que você consegue se virar." },
            ["e.Chupacabra.defense"] = new[] {
                "The lantern. Catch it in the beam and hold it there.",
                "Фонарь. Поймай её лучом и держи.",
                "Шам. Оны сәулемен іліп ал да, ұстап тұр.",
                "La linterna. Atrápala con el haz y no la sueltes.",
                "A lanterna. Pegue-a com o feixe e segure." },
            ["e.Chupacabra.hint"] = new[] {
                "It's a chupacabra. It fears light: hold your finger — the lantern — and keep it in the beam.",
                "Это чупакабра. Она боится света: зажми палец — фонарь — и держи её в луче.",
                "Бұл — чупакабра. Ол жарықтан қорқады: саусағыңды басып тұр — шам жанады — және оны сәуледе ұста.",
                "Es un chupacabras. Teme la luz: mantén el dedo pulsado (la linterna) y no lo saques del haz.",
                "É um chupa-cabra. Ele teme luz: segure o dedo (a lanterna) e mantenha-o no feixe." },
            ["e.Chupacabra.lair"] = new[] {
                "Low on the floor, in the dark — the way it waits in a pen among the animals.",
                "Низко на полу, в темноте — так она ждёт в загоне среди скотины.",
                "Еденде, қараңғыда — қорада малдың арасында осылай күтеді.",
                "Abajo, en el suelo, a oscuras: así espera en el corral entre los animales.",
                "Embaixo, no chão, no escuro — é assim que ele espera no curral entre os animais." },
            ["e.Chupacabra.tale"] = new[] {
                "In 1995, in the town of Canóvanas, eight sheep were found in a single night, each with three punctures in the neck and not a drop of blood left. A woman swore she had seen something on two legs looking at her through the window, with eyes \"like two red light bulbs\". The town turned on every light it had and kept them on for a month.",
                "В 1995 году в городке Кановане за одну ночь нашли восемь овец — у каждой три прокола на шее и ни капли крови. Одна женщина клялась, что видела в окне нечто на двух ногах с глазами «как две красные лампочки». Весь город включил все фонари и не гасил их месяц.",
                "1995 жылы Канованас қалашығында бір түнде сегіз қой табылды — әрқайсысының мойнында үш тесік, бір тамшы да қан қалмаған. Бір әйел терезеден екі аяқпен тұрған, көздері «екі қызыл шамдай» бір нәрсені көргеніне ант етті. Бүкіл қала барлық шамдарын жағып, бір ай бойы сөндірмеді.",
                "En 1995, en el pueblo de Canóvanas, aparecieron en una sola noche ocho ovejas con tres pinchazos en el cuello y sin una gota de sangre. Una mujer juró haber visto por la ventana algo en dos patas con ojos «como dos bombillas rojas». El pueblo encendió todas sus luces y no las apagó en un mes.",
                "Em 1995, na cidade de Canóvanas, oito ovelhas apareceram numa só noite, cada uma com três furos no pescoço e nenhuma gota de sangue. Uma mulher jurou ter visto pela janela algo em duas pernas com olhos \"como duas lâmpadas vermelhas\". A cidade acendeu todas as luzes e não as apagou por um mês." },
            ["e.MulaSemCabeca.name"] = new[] { "Mula sem Cabeça", "Мула-сем-Кабеса", "Мула-сем-Кабеса", "Mula sin Cabeza", "Mula sem Cabeça" },
            ["e.MulaSemCabeca.origin"] = new[] { "Brazilian folklore", "Бразильский фольклор", "Бразилия фольклоры", "Folclore brasileño", "Folclore brasileiro" },
            ["e.MulaSemCabeca.lore"] = new[] {
                "\"The headless mule.\" A cursed woman who on Thursday nights turns into a black mule with no head, flames pouring from its neck, iron horseshoes striking sparks. It gallops until the third cockcrow. The curse breaks if someone pulls the iron bridle off it — or draws blood with an iron point.",
                "«Безголовая мула». Проклятая женщина, что в ночь на пятницу превращается в чёрную мулу без головы: из шеи бьёт пламя, железные подковы высекают искры. Скачет до третьих петухов. Проклятие снимается, если сорвать с неё железную уздечку — или пустить кровь железным остриём.",
                "«Бассыз қашыр». Жұма түні басы жоқ қара қашырға айналатын қарғысқа ұшыраған әйел: мойнынан жалын атқылайды, темір тағалары ұшқын шашады. Үшінші әтеш шақырғанша шабады. Одан темір жүгенді жұлып алса — не темір ұшымен қанын шығарса, қарғыс шешіледі.",
                "«La mula sin cabeza». Una mujer maldita que la noche del jueves se convierte en una mula negra sin cabeza: del cuello le brotan llamas y las herraduras de hierro sacan chispas. Galopa hasta el tercer canto del gallo. La maldición se rompe si alguien le arranca el freno de hierro, o le saca sangre con una punta de hierro.",
                "\"A mula sem cabeça.\" Uma mulher amaldiçoada que na noite de quinta para sexta vira uma mula preta sem cabeça: do pescoço jorram chamas e as ferraduras de ferro soltam faíscas. Galopa até o terceiro canto do galo. A maldição se quebra se alguém arrancar o freio de ferro dela — ou tirar sangue com uma ponta de ferro." },
            ["e.MulaSemCabeca.signs"] = new[] {
                "Hooves on stone, a twisted neigh, the crackle of fire. It stands still — then charges in bursts, very fast.",
                "Стук копыт по камню, искажённое ржание, треск огня. Стоит — и бросается рывками, очень быстро.",
                "Тасқа тиген тұяқ дүсірі, бұрмаланған кісінеу, оттың шытырлауы. Тұрады да — өте жылдам жұлқынып атылады.",
                "Cascos sobre piedra, un relincho deformado, el crepitar del fuego. Se queda quieta y luego carga a tirones, muy rápido.",
                "Cascos na pedra, um relincho torto, o estalar do fogo. Fica parada — e investe aos trancos, muito rápido." },
            ["e.MulaSemCabeca.defense"] = new[] {
                "Iron, up close. Let it charge right up to you — and strike.",
                "Железо, вплотную. Дай ей подскочить к тебе — и бей.",
                "Темір, таяп келгенде. Саған дейін шауып келсін — сосын ұр.",
                "Hierro, de cerca. Deja que llegue a tu lado de un salto y golpea.",
                "Ferro, de perto. Deixe-a chegar até você — e golpeie." },
            ["e.MulaSemCabeca.hint"] = new[] {
                "It's the Mula sem Cabeça. It fears iron: let it come right up and double-tap the screen.",
                "Это Мула-сем-Кабеса. Она боится железа: подпусти вплотную и коснись экрана дважды.",
                "Бұл — Мула-сем-Кабеса. Ол темірден қорқады: таяп келгенде экранды екі рет түрт.",
                "Es la Mula sin Cabeza. Teme el hierro: deja que se acerque del todo y toca la pantalla dos veces.",
                "É a Mula sem Cabeça. Ela teme ferro: deixe-a chegar bem perto e toque duas vezes na tela." },
            ["e.MulaSemCabeca.lair"] = new[] {
                "Far away, at the end of the room — like the end of a dark road.",
                "Далеко, в конце комнаты — как в конце тёмной дороги.",
                "Алыста, бөлменің түкпірінде — қараңғы жолдың соңындағыдай.",
                "Lejos, al fondo de la habitación: como al final de un camino oscuro.",
                "Longe, no fundo do quarto — como no fim de uma estrada escura." },
            ["e.MulaSemCabeca.tale"] = new[] {
                "In Minas Gerais they tell of a farmhand who on a Thursday night heard hooves behind him and smelled burning. He did not run: he waited, pressed against a fence, with a horseshoe nail in his fist. When the fire was right beside him, he struck. In the morning a woman from the next village was found asleep by the road — with a scratch on her neck and no memory of the night.",
                "В Минас-Жерайсе рассказывают о батраке, который в ночь на пятницу услышал за спиной копыта и почуял гарь. Он не побежал: прижался к забору с подковным гвоздём в кулаке. Когда огонь оказался рядом, он ударил. Утром у дороги нашли спящую женщину из соседней деревни — с царапиной на шее и без памяти о ночи.",
                "Минас-Жерайста жұма түні артынан тұяқ дүсірін естіп, күйік иісін сезген жалшы туралы айтады. Ол қашпады: шарбаққа жабысып, жұдырығында таға шегесін ұстап тұрды. От жанына келгенде, ол соқты. Таңертең жол бойынан көрші ауылдың ұйықтап жатқан әйелін тапты — мойнында сызат бар, түнді мүлде есіне алмайды.",
                "En Minas Gerais cuentan de un peón que, la noche del jueves, oyó cascos a su espalda y olió a quemado. No corrió: se pegó a una cerca con un clavo de herradura en el puño. Cuando el fuego estuvo a su lado, golpeó. Por la mañana encontraron junto al camino a una mujer del pueblo vecino dormida, con un arañazo en el cuello y sin recuerdo de la noche.",
                "Em Minas Gerais contam de um peão que, numa noite de quinta, ouviu cascos atrás de si e sentiu cheiro de queimado. Não correu: encostou-se numa cerca com um prego de ferradura na mão. Quando o fogo chegou ao lado, ele golpeou. De manhã acharam à beira da estrada uma mulher da aldeia vizinha dormindo — com um arranhão no pescoço e sem lembrar nada da noite." },
            ["e.Tunda.name"] = new[] { "La Tunda", "Ла Тунда", "Ла Тунда", "La Tunda", "La Tunda" },
            ["e.Tunda.origin"] = new[] {
                "Afro-Colombian and Ecuadorian folklore",
                "Фольклор Колумбии и Эквадора",
                "Колумбия мен Эквадор фольклоры",
                "Folclore afrocolombiano y ecuatoriano",
                "Folclore afro-colombiano e equatoriano" },
            ["e.Tunda.lore"] = new[] {
                "A shapeshifter of the mangrove swamps. She takes the form of someone you love — a mother, a grandmother — but she cannot hide one thing: one of her legs is a wooden stump. She calls children into the forest in their mother's voice and keeps them there, dazed, feeding them shrimp. Drums and church bells break her spell.",
                "Оборотень мангровых болот. Принимает облик любимого человека — матери, бабушки, — но одного скрыть не может: одна нога у неё — деревянная культя. Голосом матери зовёт детей в лес и держит их там, одурманенных, кормя креветками. Барабаны и церковные колокола разрушают её чары.",
                "Мангр батпақтарының айналшағы. Сүйікті адамның — ананың, әженің — кейпіне енеді, бірақ бір нәрсені жасыра алмайды: бір аяғы ағаш тұқыл. Балаларды ананың даусымен орманға шақырып, есеңгіретіп, асшаянмен тамақтандырып ұстайды. Барабандар мен шіркеу қоңыраулары оның сиқырын бұзады.",
                "Una cambiaformas de los manglares. Toma la forma de alguien querido —una madre, una abuela—, pero no puede ocultar una cosa: una de sus piernas es un muñón de madera. Llama a los niños al monte con la voz de su madre y los retiene allí, entundados, dándoles camarones. Los tambores y las campanas de la iglesia rompen su hechizo.",
                "Uma metamorfa dos manguezais. Toma a forma de alguém querido — uma mãe, uma avó —, mas não consegue esconder uma coisa: uma das pernas é um toco de madeira. Chama as crianças para a mata com a voz da mãe e as prende lá, entorpecidas, alimentando-as com camarão. Tambores e sinos de igreja quebram o feitiço dela." },
            ["e.Tunda.signs"] = new[] {
                "A familiar woman's voice humming a lullaby slightly off key. Footsteps: one soft, one wooden. Fades and appears closer each time.",
                "Знакомый женский голос напевает колыбельную, чуть мимо нот. Шаги: один мягкий, другой — деревянный. Тает и возникает каждый раз ближе.",
                "Таныс әйел даусы бесік жырын сәл бұрмалап айтады. Қадамдар: біреуі жұмсақ, екіншісі — ағаш. Еріп жоғалып, әр жолы жақынырақ пайда болады.",
                "Una voz de mujer conocida tararea una nana un poco desafinada. Pasos: uno suave, otro de madera. Se desvanece y aparece cada vez más cerca.",
                "Uma voz de mulher conhecida cantarola uma canção de ninar meio desafinada. Passos: um macio, outro de madeira. Some e reaparece cada vez mais perto." },
            ["e.Tunda.defense"] = new[] {
                "A bell. Face her and ring — the sound breaks the spell.",
                "Колокольчик. Повернись к ней и звони — звон рвёт чары.",
                "Қоңырау. Оған бұрылып, шылдырлат — үн сиқырды бұзады.",
                "Una campanilla. Mírala de frente y hazla sonar: el sonido rompe el hechizo.",
                "Um sino. Fique de frente para ela e toque — o som quebra o feitiço." },
            ["e.Tunda.hint"] = new[] {
                "It's La Tunda. She fears the bell: face her and shake the phone.",
                "Это Ла Тунда. Она боится колокольчика: повернись к ней и встряхни телефон.",
                "Бұл — Ла Тунда. Ол қоңыраудан қорқады: оған бұрылып, телефонды сілкіле.",
                "Es La Tunda. Teme la campanilla: mírala de frente y agita el teléfono.",
                "É La Tunda. Ela teme o sino: fique de frente para ela e chacoalhe o celular." },
            ["e.Tunda.lair"] = new[] {
                "Far away, in a doorway or at the end of the hall — the way she waits at the edge of the forest.",
                "Далеко, в проёме двери или в конце коридора — так она ждёт на опушке леса.",
                "Алыста, есік ойығында не дәліздің түкпірінде — ол орман шетінде осылай күтеді.",
                "Lejos, en una puerta o al fondo del pasillo: así espera al borde del monte.",
                "Longe, numa porta ou no fim do corredor — é assim que ela espera na beira da mata." },
            ["e.Tunda.tale"] = new[] {
                "On the Pacific coast of Colombia a girl went missing for three days. She was found deep in the mangroves, smiling and silent, with shrimp shells around her. She said her mother had been with her the whole time. The village carried her home with drums beating and the church bell ringing, and only when the bell rang did she start to cry — like a child who has just woken up.",
                "На тихоокеанском побережье Колумбии три дня искали пропавшую девочку. Её нашли в глубине мангровых зарослей — улыбающуюся, молчаливую, с креветочной шелухой вокруг. Она сказала, что всё это время с ней была мама. Деревня несла её домой под барабаны и колокольный звон, и только когда зазвонил колокол, она заплакала — как ребёнок, который только что проснулся.",
                "Колумбияның Тынық мұхит жағалауында жоғалған қызды үш күн іздеді. Оны мангр тоғайының түкпірінен тапты — жымиған, үнсіз, айналасында асшаян қабықтары. Ол бүкіл уақыт бойы қасында анасы болғанын айтты. Ауыл оны барабан мен қоңырау үнімен үйге көтеріп әкелді, тек қоңырау соғылғанда ғана ол жылап жіберді — жаңа оянған баладай.",
                "En la costa pacífica de Colombia buscaron durante tres días a una niña desaparecida. La encontraron en lo hondo del manglar, sonriente y callada, rodeada de cáscaras de camarón. Dijo que su madre había estado con ella todo el tiempo. El pueblo la llevó a casa entre tambores y campanas, y solo cuando sonó la campana se echó a llorar, como una niña que acaba de despertar.",
                "Na costa do Pacífico da Colômbia procuraram por três dias uma menina desaparecida. Encontraram-na no fundo do manguezal — sorrindo, calada, com cascas de camarão em volta. Ela disse que a mãe tinha estado com ela o tempo todo. A aldeia a levou para casa ao som de tambores e do sino, e só quando o sino tocou ela começou a chorar — como uma criança que acabou de acordar." },
            ["c.Prints.name"] = new[] { "Prints", "Следы", "Іздер", "Huellas", "Pegadas" },
            ["c.Prints.howto"] = new[] {
                "In the thermal camera, cold footprints appear on the floor and lead toward the lair.",
                "В тепловизоре на полу проступают холодные следы — они ведут к логову.",
                "Тепловизорда еденде суық іздер пайда болады — олар ұяға апарады.",
                "En la cámara térmica aparecen en el suelo huellas frías que llevan hacia la guarida.",
                "Na câmera térmica aparecem no chão pegadas frias que levam até o covil." },
            ["n.Prints"] = new[] { "Something walked across the floor… {0}", "Кто-то прошёл по полу… {0}", "Еденмен біреу жүріп өтті… {0}", "Algo ha cruzado el suelo… {0}", "Algo atravessou o chão… {0}" },
            ["h.Prints"] = new[] {
                "Switch on the thermal camera and look at the floor. Cold footprints — mark “Prints”.",
                "Включи тепловизор и посмотри на пол. Холодные следы — отметь «Следы».",
                "Тепловизорды қосып, еденге қара. Суық іздер болса — «Іздер» белгіле.",
                "Activa la cámara térmica y mira el suelo. Huellas frías: marca «Huellas».",
                "Ligue a câmera térmica e olhe para o chão. Pegadas frias — marque “Pegadas”." },
            ["e.Pontianak.name"] = new[] { "Pontianak", "Понтианак", "Понтианак", "Pontianak", "Pontianak" },
            ["e.Pontianak.origin"] = new[] { "Malay and Indonesian folklore", "Малайский и индонезийский фольклор", "Малай және индонезия фольклоры", "Folclore malayo e indonesio", "Folclore malaio e indonésio" },
            ["e.Pontianak.lore"] = new[] {
                "The spirit of a woman who died in childbirth. A pale beauty in white with long black hair and red eyes, smelling of frangipani flowers — and then of rot. Her baby's cry is the warning: if it sounds far away, she is right beside you. In Malaya they say an iron nail driven into the hollow at the back of her neck turns her back into a quiet woman.",
                "Дух женщины, умершей родами. Бледная красавица в белом, с длинными чёрными волосами и красными глазами; пахнет цветами франжипани — а потом тленом. Её предупреждение — плач младенца: если он звучит издалека, она совсем рядом. В Малайе говорят: железный гвоздь, вбитый в ямку на затылке, снова делает её тихой женщиной.",
                "Босана алмай өлген әйелдің рухы. Ақ киімді, қара шашы ұзын, көзі қызыл бозғылт сұлу; франжипани гүлінің иісі шығады — сосын шіріктің иісі. Оның ескертуі — нәрестенің жылауы: егер ол алыстан естілсе, ол дәл қасыңда. Малайяда айтады: желкесіндегі шұңқырға қағылған темір шеге оны қайтадан момын әйелге айналдырады.",
                "El espíritu de una mujer que murió al dar a luz. Una belleza pálida de blanco, con largo pelo negro y ojos rojos, que huele a flores de frangipani… y luego a podredumbre. Su aviso es el llanto de un bebé: si suena lejos, está justo a tu lado. En Malasia dicen que un clavo de hierro clavado en el hueco de la nuca la vuelve una mujer tranquila.",
                "O espírito de uma mulher que morreu no parto. Uma beldade pálida de branco, de cabelo preto comprido e olhos vermelhos, que cheira a flores de jasmim-manga — e depois a podridão. O aviso é o choro de um bebê: se soar longe, ela está bem ao seu lado. Na Malásia dizem que um prego de ferro cravado na nuca dela a transforma de novo numa mulher calma." },
            ["e.Pontianak.signs"] = new[] {
                "A baby crying — the farther it sounds, the closer she is. She floats closer, vanishes, and appears nearer still.",
                "Плач младенца — чем дальше он звучит, тем она ближе. Подплывает, исчезает и возникает ещё ближе.",
                "Нәрестенің жылауы — ол неғұрлым алыстан естілсе, ол соғұрлым жақын. Қалқып жақындап, жоғалып, одан да жақын пайда болады.",
                "Llanto de bebé: cuanto más lejos suena, más cerca está ella. Flota hacia ti, desaparece y aparece aún más cerca.",
                "Choro de bebê — quanto mais longe soa, mais perto ela está. Flutua para perto, some e aparece ainda mais perto." },
            ["e.Pontianak.defense"] = new[] {
                "Iron, up close. Let her float right up to your face — and strike.",
                "Железо, вплотную. Дай ей подплыть к самому лицу — и бей.",
                "Темір, таяп келгенде. Бетіңе дейін қалқып келсін — сосын ұр.",
                "Hierro, de cerca. Deja que llegue flotando hasta tu cara y golpea.",
                "Ferro, de perto. Deixe-a flutuar até o seu rosto — e golpeie." },
            ["e.Pontianak.hint"] = new[] {
                "It's a pontianak. She fears iron: let her come right up and double-tap the screen.",
                "Это понтианак. Она боится железа: подпусти вплотную и коснись экрана дважды.",
                "Бұл — понтианак. Ол темірден қорқады: таяп келгенде экранды екі рет түрт.",
                "Es una pontianak. Teme el hierro: deja que se acerque del todo y toca la pantalla dos veces.",
                "É uma pontianak. Ela teme ferro: deixe-a chegar bem perto e toque duas vezes na tela." },
            ["e.Pontianak.lair"] = new[] {
                "Close by, at the edge of sight — the way she waits in a banana grove beside the path.",
                "Рядом, на краю зрения — так она ждёт в банановой роще у тропы.",
                "Жақын, көздің шетінде — ол соқпақ жанындағы банан тоғайында осылай күтеді.",
                "Cerca, al borde de la vista: así espera en un platanal junto al sendero.",
                "Perto, no canto do olho — é assim que ela espera num bananal à beira da trilha." },
            ["e.Pontianak.tale"] = new[] {
                "A taxi driver in Kuala Lumpur picked up a woman in white on an empty road at night. She asked to be taken to the cemetery. In the mirror the back seat was empty, but the smell of frangipani filled the car. When he stopped, a baby began to cry far away — and the driver's hair was pulled from behind.",
                "Таксист в Куала-Лумпуре ночью подобрал на пустой дороге женщину в белом. Она попросила отвезти её к кладбищу. В зеркале заднее сиденье было пустым, но машину заполнил запах франжипани. Когда он остановился, где-то далеко заплакал младенец — и кто-то сзади потянул его за волосы.",
                "Куала-Лумпурдағы такси жүргізушісі түнде бос жолдан ақ киімді әйелді отырғызды. Ол зиратқа апаруды өтінді. Айнада артқы орындық бос еді, бірақ көлікті франжипани иісі кернеді. Ол тоқтағанда, алыста бір нәресте жылап қоя берді — артынан біреу оның шашынан тартты.",
                "Un taxista de Kuala Lumpur recogió de noche, en una carretera vacía, a una mujer de blanco. Le pidió que la llevara al cementerio. En el espejo el asiento trasero estaba vacío, pero el coche se llenó de olor a frangipani. Cuando se detuvo, un bebé empezó a llorar a lo lejos, y alguien le tiró del pelo desde atrás.",
                "Um taxista de Kuala Lumpur pegou à noite, numa estrada vazia, uma mulher de branco. Ela pediu para ir ao cemitério. No retrovisor o banco de trás estava vazio, mas o carro se encheu do cheiro de jasmim-manga. Quando ele parou, um bebê começou a chorar ao longe — e alguém puxou o cabelo dele por trás." },
            ["e.Penanggalan.name"] = new[] { "Penanggalan", "Пенанггалан", "Пенанггалан", "Penanggalan", "Penanggalan" },
            ["e.Penanggalan.origin"] = new[] { "Malay folklore", "Малайский фольклор", "Малай фольклоры", "Folclore malayo", "Folclore malaio" },
            ["e.Penanggalan.lore"] = new[] {
                "By day — an ordinary midwife from the village. At night her head tears free of her body and flies out with the entrails dangling beneath it, glistening, looking for blood. Her body waits at home in a jar of vinegar. Villagers hung thorny pandan leaves over doors and windows: her entrails catch on the thorns, and she flees.",
                "Днём — обычная деревенская повитуха. Ночью её голова отрывается от тела и вылетает в окно, а под ней свисают блестящие внутренности — она ищет кровь. Тело ждёт дома в кадке с уксусом. В деревнях вешали над дверьми и окнами колючие листья пандана: внутренности цепляются за колючки, и она бежит.",
                "Күндіз — ауылдың қарапайым кіндік шешесі. Түнде басы денесінен жұлынып, астында жылтыраған ішек-қарны салбырап, терезеден ұшып шығады — қан іздейді. Денесі үйде сірке су толы күбіде күтеді. Ауылдарда есік пен терезенің үстіне тікенді пандан жапырақтарын ілген: ішектері тікенге ілініп, ол қашады.",
                "De día, una partera normal del pueblo. De noche su cabeza se desprende del cuerpo y sale volando con las entrañas colgando debajo, relucientes, en busca de sangre. El cuerpo la espera en casa en una tinaja de vinagre. En los pueblos colgaban hojas espinosas de pandan sobre puertas y ventanas: las entrañas se enganchan en las espinas, y ella huye.",
                "De dia, uma parteira comum da aldeia. À noite a cabeça se solta do corpo e sai voando com as vísceras penduradas embaixo, brilhando, em busca de sangue. O corpo a espera em casa num pote de vinagre. Nas aldeias penduravam folhas espinhosas de pandano sobre portas e janelas: as vísceras se prendem nos espinhos, e ela foge." },
            ["e.Penanggalan.signs"] = new[] {
                "Dripping, a wet flapping in the dark. A floating head circles around you, a little closer with each turn.",
                "Капание, мокрое хлопанье в темноте. Летящая голова кружит вокруг тебя, с каждым кругом чуть ближе.",
                "Тамшылау, қараңғыдағы дымқыл сарт-сұрт. Ұшқан бас айналаңда айналып, әр айналған сайын сәл жақындайды.",
                "Goteo, un aleteo húmedo en la oscuridad. Una cabeza flotante gira a tu alrededor, un poco más cerca en cada vuelta.",
                "Gotejar, um bater úmido no escuro. Uma cabeça voadora circula ao seu redor, um pouco mais perto a cada volta." },
            ["e.Penanggalan.defense"] = new[] {
                "Wormwood — bitter, thorny herbs. Catch her in your sight as she circles and wave the bunch.",
                "Полынь — горькие колючие травы. Поймай её взглядом на круге и взмахни пучком.",
                "Жусан — ащы, тікенді шөптер. Айналып жүргенде оны көзіңмен іліп, шоқты сілте.",
                "Ajenjo: hierbas amargas y espinosas. Atrápala con la mirada mientras gira y agita el manojo.",
                "Losna — ervas amargas e espinhosas. Pegue-a com o olhar enquanto circula e agite o maço." },
            ["e.Penanggalan.hint"] = new[] {
                "It's a penanggalan. She fears bitter herbs: follow her with your eyes and zigzag your finger left and right.",
                "Это пенанггалан. Она боится горьких трав: проследи за ней взглядом и проведи пальцем зигзагом влево-вправо.",
                "Бұл — пенанггалан. Ол ащы шөптерден қорқады: оны көзіңмен бақылап, саусағыңды солға-оңға ирек етіп жүргіз.",
                "Es una penanggalan. Teme las hierbas amargas: síguela con la mirada y haz un zigzag con el dedo.",
                "É uma penanggalan. Ela teme ervas amargas: siga-a com o olhar e faça um zigue-zague com o dedo." },
            ["e.Penanggalan.lair"] = new[] {
                "High up, under the ceiling — the way she hangs under the eaves of a house.",
                "Высоко, под потолком — так она висит под стрехой дома.",
                "Жоғарыда, төбенің астында — ол үйдің шатыр шетінің астында осылай салбырап тұрады.",
                "Arriba, bajo el techo: así cuelga bajo el alero de una casa.",
                "No alto, sob o teto — é assim que ela fica pendurada sob o beiral de uma casa." },
            ["e.Penanggalan.tale"] = new[] {
                "A man once found a jar of vinegar in his new wife's room — with a woman's body sitting in it, headless. Instead of running, he filled the jar with broken glass and thorns. At dawn something flew in through the window, tried to get back in — and screamed until the sun rose. That was the end of the village's sickness among newborns.",
                "Однажды мужчина нашёл в комнате молодой жены кадку с уксусом — а в ней сидело женское тело без головы. Вместо того чтобы бежать, он насыпал в кадку битого стекла и колючек. На рассвете в окно что-то влетело, попыталось вернуться — и кричало, пока не взошло солнце. С тех пор младенцы в деревне больше не болели.",
                "Бірде бір ер адам жас әйелінің бөлмесінен сірке су толы күбі тапты — ішінде басы жоқ әйел денесі отырды. Қашудың орнына ол күбіге сынған шыны мен тікен салды. Таң ата терезеден бірдеңе ұшып кіріп, қайта оралмақ болды — күн шыққанша айқайлады. Содан бері ауылда нәрестелер ауырмайтын болды.",
                "Una vez un hombre encontró en el cuarto de su joven esposa una tinaja de vinagre, y dentro, sentado, un cuerpo de mujer sin cabeza. En vez de huir, llenó la tinaja de vidrios rotos y espinas. Al amanecer algo entró volando por la ventana, intentó volver a su sitio… y gritó hasta que salió el sol. Desde entonces los recién nacidos del pueblo no volvieron a enfermar.",
                "Certa vez um homem encontrou no quarto da jovem esposa um pote de vinagre — e dentro dele, sentado, um corpo de mulher sem cabeça. Em vez de fugir, encheu o pote de cacos de vidro e espinhos. Ao amanhecer algo entrou voando pela janela, tentou voltar para o lugar — e gritou até o sol nascer. Desde então os recém-nascidos da aldeia não adoeceram mais." },
            ["e.Aswang.name"] = new[] { "Aswang", "Асванг", "Асванг", "Aswang", "Aswang" },
            ["e.Aswang.origin"] = new[] { "Filipino folklore", "Филиппинский фольклор", "Филиппин фольклоры", "Folclore filipino", "Folclore filipino" },
            ["e.Aswang.lore"] = new[] {
                "A shapeshifter who lives among people: a quiet neighbour by day, at night a creature with bat wings and a long tongue like a thread. Its reflection in your eyes is upside down. It announces itself with a \"tik-tik\" sound — and the softer it gets, the closer it is. In the provinces they keep salt at the window: thrown at an aswang, salt burns like fire.",
                "Оборотень, что живёт среди людей: днём — тихий сосед, ночью — тварь с перепончатыми крыльями и длинным, как нить, языком. Её отражение в твоих глазах — вверх ногами. Выдаёт себя звуком «тик-тик» — и чем он тише, тем она ближе. В провинциях держат у окна соль: брошенная в асванга, соль жжёт, как огонь.",
                "Адамдардың арасында тұратын айналшақ: күндіз — момын көрші, түнде — жарғақ қанатты, жіптей ұзын тілді мақұлық. Сенің көзіңдегі оның бейнесі — төңкеріліп тұрады. Өзін «тік-тік» деген дыбыспен білдіреді — ол неғұрлым ақырын болса, соғұрлым жақын. Провинцияларда терезе жанында тұз ұстайды: асвангқа лақтырылған тұз оттай күйдіреді.",
                "Un cambiaformas que vive entre la gente: de día, un vecino tranquilo; de noche, una criatura con alas de murciélago y una lengua larga como un hilo. Su reflejo en tus ojos aparece al revés. Se anuncia con un «tik-tik», y cuanto más bajo suena, más cerca está. En las provincias guardan sal junto a la ventana: lanzada a un aswang, quema como el fuego.",
                "Um metamorfo que vive entre as pessoas: de dia, um vizinho quieto; à noite, uma criatura de asas de morcego e língua comprida como um fio. O reflexo dele nos seus olhos aparece de cabeça para baixo. Ele se anuncia com um \"tik-tik\" — e quanto mais baixo, mais perto está. Nas províncias guardam sal perto da janela: jogado num aswang, o sal queima como fogo." },
            ["e.Aswang.signs"] = new[] {
                "\"Tik-tik… tik-tik…\" — quieter means closer. The flap of wings. It moves only when you are not looking, and loves to come up from behind.",
                "«Тик-тик… тик-тик…» — тише значит ближе. Хлопанье крыльев. Движется, только когда на неё не смотрят, и любит заходить со спины.",
                "«Тік-тік… тік-тік…» — ақырын болса, жақын деген сөз. Қанат сарт-сұрты. Оған қарамағанда ғана қозғалады, арттан келгенді жақсы көреді.",
                "«Tik-tik… tik-tik…»: más bajo significa más cerca. Un aleteo. Solo se mueve cuando no lo miras y le gusta llegar por la espalda.",
                "\"Tik-tik… tik-tik…\" — mais baixo quer dizer mais perto. Um bater de asas. Só se move quando ninguém olha e gosta de chegar por trás." },
            ["e.Aswang.defense"] = new[] {
                "Salt. Turn around fast and throw it right in its face.",
                "Соль. Резко обернись и брось её прямо в морду.",
                "Тұз. Тез бұрылып, тура тұмсығына шаш.",
                "Sal. Date la vuelta rápido y lánzasela a la cara.",
                "Sal. Vire-se rápido e jogue bem na cara dele." },
            ["e.Aswang.hint"] = new[] {
                "It's an aswang. It fears salt: look at it and swipe up.",
                "Это асванг. Он боится соли: посмотри на него и смахни пальцем вверх.",
                "Бұл — асванг. Ол тұздан қорқады: оған қарап, саусақпен жоғары сырғыт.",
                "Es un aswang. Teme la sal: míralo y desliza hacia arriba.",
                "É um aswang. Ele teme sal: olhe para ele e deslize para cima." },
            ["e.Aswang.lair"] = new[] {
                "Behind you — where you weren't looking when the night began.",
                "За спиной — там, куда не падал взгляд, когда началась ночь.",
                "Арқаңда — түн басталғанда сен қарамаған жақта.",
                "A tu espalda: donde no mirabas cuando empezó la noche.",
                "Atrás de você — onde você não estava olhando quando a noite começou." },
            ["e.Aswang.tale"] = new[] {
                "In a village on Capiz, a pregnant woman heard \"tik-tik\" on the roof: far, far away. Her grandmother knew better and put a bowl of salt by her bed and a mirror over the door. At midnight the mirror showed a face looking in from the ceiling — upside down. The grandmother threw the salt up into the dark, and something fell onto the roof and scrambled away, screeching.",
                "В деревне на острове Капис беременная женщина услышала на крыше «тик-тик»: далеко-далеко. Её бабушка знала лучше: поставила у кровати миску соли, а над дверью — зеркало. В полночь зеркало показало лицо, смотрящее с потолка, — вверх ногами. Бабушка швырнула соль вверх, в темноту, и что-то рухнуло на крышу и, визжа, уползло.",
                "Капис аралындағы ауылда жүкті әйел шатырдан «тік-тік» дегенді естіді: алыс-алыстан. Әжесі жақсы білетін: төсектің жанына бір тостаған тұз, есіктің үстіне айна қойды. Түн ортасында айна төбеден қарап тұрған бетті көрсетті — төңкеріліп тұрған. Әжесі тұзды жоғары, қараңғыға лақтырды, бірдеңе шатырға құлап, шыңғырып жорғалап кетті.",
                "En un pueblo de Capiz, una mujer embarazada oyó «tik-tik» en el tejado: muy, muy lejos. Su abuela sabía más: puso un cuenco de sal junto a la cama y un espejo sobre la puerta. A medianoche el espejo mostró una cara mirando desde el techo, al revés. La abuela lanzó la sal hacia arriba, a la oscuridad, y algo cayó sobre el tejado y huyó chillando.",
                "Numa aldeia de Capiz, uma mulher grávida ouviu \"tik-tik\" no telhado: longe, bem longe. A avó sabia mais: pôs uma tigela de sal ao lado da cama e um espelho sobre a porta. À meia-noite o espelho mostrou um rosto olhando do teto — de cabeça para baixo. A avó jogou o sal para cima, no escuro, e algo caiu no telhado e fugiu guinchando." },
            ["e.Kuchisake.name"] = new[] { "Kuchisake-onna", "Кутисакэ-онна", "Кутисакэ-онна", "Kuchisake-onna", "Kuchisake-onna" },
            ["e.Kuchisake.origin"] = new[] { "Japanese folklore", "Японский фольклор", "Жапон фольклоры", "Folclore japonés", "Folclore japonês" },
            ["e.Kuchisake.lore"] = new[] {
                "\"The slit-mouthed woman.\" A tall woman in a long coat with a mask over her face stops you on the street at dusk and asks: \"Am I pretty?\" Say no — she kills you with her scissors. Say yes — she takes off the mask: her mouth is cut from ear to ear. \"Even now?\" They say she cannot stand to see her own face: a mirror held up to her makes her flee.",
                "«Женщина с разрезанным ртом». Высокая женщина в длинном пальто, с маской на лице, останавливает тебя в сумерках и спрашивает: «Я красивая?» Скажешь «нет» — убьёт ножницами. Скажешь «да» — снимет маску: рот разрезан от уха до уха. «А теперь?» Говорят, она не выносит своего лица: поднесённое к ней зеркало обращает её в бегство.",
                "«Аузы тілінген әйел». Ұзын пальтолы, бетінде маскасы бар ұзын бойлы әйел ымыртта сені тоқтатып: «Мен сұлумын ба?» — деп сұрайды. «Жоқ» десең — қайшымен өлтіреді. «Иә» десең — маскасын шешеді: аузы құлақтан құлаққа дейін тілінген. «Ал енді ше?» Ол өз бетін көруге шыдамайды дейді: оған тосылған айна оны қашырады.",
                "«La mujer de la boca cortada». Una mujer alta con un abrigo largo y una mascarilla te detiene al anochecer y pregunta: «¿Soy bonita?». Si dices que no, te mata con sus tijeras. Si dices que sí, se quita la mascarilla: la boca está rajada de oreja a oreja. «¿Y ahora?». Dicen que no soporta ver su propio rostro: un espejo frente a ella la hace huir.",
                "\"A mulher da boca cortada.\" Uma mulher alta de casaco comprido e máscara no rosto para você na rua ao entardecer e pergunta: \"Eu sou bonita?\" Se disser não, ela mata você com a tesoura. Se disser sim, ela tira a máscara: a boca está cortada de orelha a orelha. \"E agora?\" Dizem que ela não suporta ver o próprio rosto: um espelho erguido diante dela a faz fugir." },
            ["e.Kuchisake.signs"] = new[] {
                "The snip of scissors, a woman's voice asking a question. She appears close and simply stands there; every second you look at her, your fear grows. Then she strikes.",
                "Щёлканье ножниц, женский голос, задающий вопрос. Возникает рядом и просто стоит; каждую секунду, что ты на неё смотришь, страх растёт. Потом — удар.",
                "Қайшының шыртылы, сұрақ қойған әйел даусы. Жаныңда пайда болып, жай ғана тұрады; оған қараған әр секунд сайын қорқыныш өседі. Сосын — соққы.",
                "El chasquido de unas tijeras, una voz de mujer que hace una pregunta. Aparece cerca y se queda quieta; cada segundo que la miras, el miedo crece. Luego ataca.",
                "O estalo de uma tesoura, uma voz de mulher fazendo uma pergunta. Ela surge perto e fica parada; a cada segundo que você olha para ela, o medo cresce. Depois, o golpe." },
            ["e.Kuchisake.defense"] = new[] {
                "A mirror. Show her her own face — quickly, without staring.",
                "Зеркало. Покажи ей её лицо — быстро, не глядя на неё долго.",
                "Айна. Оған өз бетін көрсет — тез, ұзақ қарамай.",
                "Un espejo. Muéstrale su propia cara, rápido, sin mirarla demasiado.",
                "Um espelho. Mostre a ela o próprio rosto — rápido, sem encará-la." },
            ["e.Kuchisake.hint"] = new[] {
                "It's Kuchisake-onna. Don't stare at her! She fears the mirror: glance at her and swipe down.",
                "Это Кутисакэ-онна. Не смотри на неё долго! Она боится зеркала: взгляни на неё и смахни пальцем вниз.",
                "Бұл — Кутисакэ-онна. Оған ұзақ қарама! Ол айнадан қорқады: оған бір қарап, саусақпен төмен сырғыт.",
                "Es Kuchisake-onna. ¡No te quedes mirándola! Teme el espejo: mírala un instante y desliza hacia abajo.",
                "É Kuchisake-onna. Não fique encarando! Ela teme o espelho: olhe de relance e deslize para baixo." },
            ["e.Kuchisake.lair"] = new[] {
                "Close, at arm's length — the way she steps out to meet you on an evening street.",
                "Близко, на расстоянии руки — так она выходит навстречу на вечерней улице.",
                "Жақын, қол созым жерде — кешкі көшеде ол қарсы алдыңнан осылай шығады.",
                "Cerca, a un brazo de distancia: así te sale al paso en una calle al anochecer.",
                "Perto, a um braço de distância — é assim que ela aparece numa rua ao anoitecer." },
            ["e.Kuchisake.tale"] = new[] {
                "In 1979 the rumours spread so fast through Japan that schools sent children home in groups, escorted by teachers. Children carried hand mirrors in their pockets and were taught the answer: \"You're average.\" A boy from Gifu said a woman in a mask stopped him by the rice field. He held up his mirror without looking. When he opened his eyes, only her scissors lay on the road.",
                "В 1979 году слухи разошлись по Японии так быстро, что школы отпускали детей домой группами, в сопровождении учителей. Дети носили в карманах зеркальца, их учили ответу: «Ты обычная». Мальчик из Гифу рассказывал, что у рисового поля его остановила женщина в маске. Он поднял зеркальце, не глядя. Когда он открыл глаза, на дороге лежали только её ножницы.",
                "1979 жылы қауесет Жапонияға тез тарағаны сонша, мектептер балаларды үйге топ-тобымен, мұғалімдердің ертуімен жіберді. Балалар қалталарында кішкене айна алып жүрді, оларға «Сен қарапайымсың» деп жауап беруді үйретті. Гифудан келген бала күріш алқабының жанында маскалы әйел тоқтатқанын айтты. Ол қарамастан айнаны көтерді. Көзін ашқанда, жолда тек оның қайшысы жатты.",
                "En 1979 el rumor corrió tan rápido por Japón que las escuelas enviaban a los niños a casa en grupos, acompañados por maestros. Los niños llevaban espejitos en los bolsillos y aprendían la respuesta: «Eres normal». Un niño de Gifu contó que una mujer con mascarilla lo detuvo junto a un arrozal. Él levantó el espejo sin mirar. Cuando abrió los ojos, en el camino solo estaban sus tijeras.",
                "Em 1979 o boato correu tão rápido pelo Japão que as escolas mandavam as crianças para casa em grupos, acompanhadas de professores. As crianças levavam espelhinhos no bolso e aprendiam a resposta: \"Você é comum.\" Um menino de Gifu contou que uma mulher de máscara o parou perto de um arrozal. Ele ergueu o espelho sem olhar. Quando abriu os olhos, na estrada só estava a tesoura dela." },
            ["e.Jiangshi.name"] = new[] { "Jiangshi", "Цзянши", "Цзянши", "Jiangshi", "Jiangshi" },
            ["e.Jiangshi.origin"] = new[] { "Chinese folklore", "Китайский фольклор", "Қытай фольклоры", "Folclore chino", "Folclore chinês" },
            ["e.Jiangshi.lore"] = new[] {
                "A \"stiff corpse\" in an old official's robe. Its body has not bent since death, so it moves in jumps, arms stretched out in front. It is blind and finds the living by their breath — hold your breath, and it passes by. Taoist priests led such corpses home by night, ringing a bell: the sound of the bell commands them.",
                "«Окоченевший труп» в старом чиновничьем халате. Тело не гнётся с самой смерти, поэтому он передвигается прыжками, вытянув руки перед собой. Он слеп и находит живых по дыханию — задержи дыхание, и он пройдёт мимо. Даосские жрецы по ночам вели таких мертвецов домой, звоня в колокольчик: звон им приказывает.",
                "Ескі шенеунік шапанын киген «қатып қалған өлік». Денесі өлгеннен бері бүгілмейді, сондықтан ол қолын алға созып, секіріп жүреді. Ол соқыр, тірілерді тынысынан табады — тынысыңды ұста, ол жаныңнан өтіп кетеді. Даос абыздары мұндай өліктерді түнде қоңырау соғып үйлеріне бастап апаратын: қоңырау үні оларға бұйырады.",
                "Un «cadáver rígido» con la túnica de un antiguo funcionario. Su cuerpo no se ha doblado desde la muerte, así que se mueve a saltos, con los brazos extendidos al frente. Es ciego y encuentra a los vivos por su aliento: contén la respiración y pasará de largo. Los sacerdotes taoístas guiaban de noche a estos muertos hasta su casa tocando una campanilla: su sonido les da órdenes.",
                "Um \"cadáver rígido\" com o manto de um antigo funcionário. O corpo não dobra desde a morte, então ele se move aos saltos, de braços estendidos para a frente. É cego e encontra os vivos pela respiração — prenda o fôlego, e ele passa direto. Os sacerdotes taoístas conduziam à noite esses mortos de volta para casa tocando um sino: o som do sino os comanda." },
            ["e.Jiangshi.signs"] = new[] {
                "Heavy thuds of jumping, the jingle of a little bell on its belt. It stands still — then leaps toward you. Silence and stillness hide you from it.",
                "Тяжёлые удары прыжков, звяканье колокольчика на поясе. Стоит неподвижно — и прыгает к тебе. Тишина и неподвижность прячут от него.",
                "Ауыр секірістің дүрсілі, белдігіндегі қоңыраудың сыңғыры. Қимылсыз тұрады да — саған қарай секіреді. Тыныштық пен қимылсыздық сені одан жасырады.",
                "Golpes pesados de saltos, el tintineo de una campanilla en su cinturón. Se queda quieto y luego salta hacia ti. El silencio y la quietud te esconden de él.",
                "Baques pesados de saltos, o tilintar de um sininho na cintura. Fica parado — e salta na sua direção. Silêncio e imobilidade escondem você dele." },
            ["e.Jiangshi.defense"] = new[] {
                "A bell. Face it and ring — the bell commands it to stop.",
                "Колокольчик. Повернись к нему и звони — звон велит ему остановиться.",
                "Қоңырау. Оған бұрылып, шылдырлат — үн оған тоқта деп бұйырады.",
                "Una campanilla. Mírala de frente y hazla sonar: el sonido le ordena detenerse.",
                "Um sino. Fique de frente para ele e toque — o som manda que ele pare." },
            ["e.Jiangshi.hint"] = new[] {
                "It's a jiangshi. It fears the bell: face it and shake the phone. On the hunt — keep quiet, it hunts by breath.",
                "Это цзянши. Он боится колокольчика: повернись к нему и встряхни телефон. На охоте — молчи, он ищет по дыханию.",
                "Бұл — цзянши. Ол қоңыраудан қорқады: оған бұрылып, телефонды сілкіле. Аңда — үнсіз бол, ол тыныстан іздейді.",
                "Es un jiangshi. Teme la campanilla: míralo de frente y agita el teléfono. En la caza, guarda silencio: te busca por el aliento.",
                "É um jiangshi. Ele teme o sino: fique de frente para ele e chacoalhe o celular. Na caçada, fique quieto — ele caça pela respiração." },
            ["e.Jiangshi.lair"] = new[] {
                "In the darkest corner, standing upright — like a coffin left in a temple.",
                "В самом тёмном углу, стоя — как гроб, оставленный в храме.",
                "Ең қараңғы бұрышта, тік тұрып — ғибадатханада қалдырылған табыт сияқты.",
                "En el rincón más oscuro, de pie: como un ataúd olvidado en un templo.",
                "No canto mais escuro, de pé — como um caixão esquecido num templo." },
            ["e.Jiangshi.tale"] = new[] {
                "Travellers in Hunan told of a night inn where a priest arrived with a line of corpses in straw hats, a yellow talisman on each forehead. He rang his bell, and they hopped into the back room. At midnight a draught tore one talisman off. The innkeeper's son held his breath until dawn, while something stood beside his bed, sniffing. The priest's bell found it before the sun did.",
                "Путники в Хунани рассказывали о постоялом дворе, куда ночью пришёл жрец с вереницей мертвецов в соломенных шляпах, у каждого на лбу жёлтый талисман. Он позвонил в колокольчик — и они запрыгали в заднюю комнату. В полночь сквозняк сорвал один талисман. Сын хозяина до рассвета не дышал, а у его кровати стояло что-то и принюхивалось. Колокольчик жреца нашёл его раньше, чем солнце.",
                "Хунаньдағы жолаушылар бір қонақүй туралы айтатын: түнде оған сабан қалпақ киген, әрқайсысының маңдайында сары тұмары бар бір тізбек өлікті ертіп абыз келді. Ол қоңырау соқты — олар секіріп артқы бөлмеге кірді. Түн ортасында жел бір тұмарды жұлып кетті. Қожайынның ұлы таң атқанша тыныс алмады, ал төсегінің жанында бірдеңе тұрып иіскелеп жатты. Абыздың қоңырауы оны күннен бұрын тапты.",
                "Los viajeros de Hunan contaban de una posada a la que una noche llegó un sacerdote con una fila de cadáveres con sombreros de paja y un talismán amarillo en la frente. Tocó su campanilla y ellos entraron saltando al cuarto del fondo. A medianoche una corriente arrancó un talismán. El hijo del posadero contuvo la respiración hasta el alba, mientras algo junto a su cama olfateaba. La campanilla del sacerdote lo encontró antes que el sol.",
                "Viajantes de Hunan contavam de uma estalagem onde, certa noite, chegou um sacerdote com uma fila de cadáveres de chapéu de palha e um talismã amarelo na testa. Ele tocou o sino, e eles entraram pulando no quarto dos fundos. À meia-noite uma corrente de ar arrancou um talismã. O filho do estalajadeiro prendeu a respiração até o amanhecer, enquanto algo ao lado da cama farejava. O sino do sacerdote o encontrou antes do sol." },
            ["e.Shurale.name"] = new[] { "Shurale", "Шурале", "Шүрәле", "Shurale", "Shurale" },
            ["e.Shurale.origin"] = new[] { "Tatar and Bashkir folklore", "Татарский и башкирский фольклор", "Татар және башқұрт фольклоры", "Folclore tártaro y baskir", "Folclore tártaro e bashkir" },
            ["e.Shurale.lore"] = new[] {
                "A forest spirit, tall and hairy, with a horn on its forehead and fingers so long they bend like branches. It laughs and calls travellers deeper into the forest, then tickles them until they die. In Tukay's tale a woodcutter tricked it into putting its fingers into a split log and knocked out the iron wedge: iron is what holds a shurale.",
                "Лесной дух, высокий и косматый, с рогом на лбу и такими длинными пальцами, что они гнутся, как ветки. Смеётся и зазывает путников в чащу, а потом защекочивает до смерти. В сказке Тукая дровосек обманом заставил его сунуть пальцы в расколотое бревно и выбил железный клин: держит шурале только железо.",
                "Ұзын бойлы, түкті, маңдайында мүйізі бар, саусақтары бұтақтай иілетін орман рухы. Күліп, жолаушыларды орманның түкпіріне шақырады, сосын қытықтап өлтіреді. Тоқайдың ертегісінде отыншы оны алдап, саусақтарын жарылған бөренеге тығуға мәжбүр етіп, темір сынаны қағып алды: шүрәлені тек темір ұстайды.",
                "Un espíritu del bosque, alto y peludo, con un cuerno en la frente y dedos tan largos que se doblan como ramas. Ríe y llama a los viajeros hacia lo más espeso del bosque, y luego les hace cosquillas hasta matarlos. En el cuento de Tukay, un leñador lo engañó para que metiera los dedos en un tronco partido y sacó la cuña de hierro: solo el hierro sujeta a un shurale.",
                "Um espírito da floresta, alto e peludo, com um chifre na testa e dedos tão longos que se dobram como galhos. Ri e chama os viajantes para o fundo da mata, depois faz cócegas até matá-los. No conto de Tukay, um lenhador o enganou para enfiar os dedos num tronco rachado e arrancou a cunha de ferro: só o ferro prende um shurale." },
            ["e.Shurale.signs"] = new[] {
                "Branches creaking, a fast tickling laugh. It moves only when you are not looking — and fast. Its fingers reach for you from behind.",
                "Скрип веток, быстрый щекочущий смех. Движется, только когда на него не смотрят, — и быстро. Его пальцы тянутся к тебе со спины.",
                "Бұтақтардың сықыры, жылдам қытықтаған күлкі. Оған қарамағанда ғана қозғалады — әрі жылдам. Саусақтары арттан саған созылады.",
                "Ramas que crujen, una risa rápida de cosquillas. Solo se mueve cuando no lo miras, y deprisa. Sus dedos te buscan por la espalda.",
                "Galhos rangendo, uma risada rápida de cócegas. Só se move quando ninguém olha — e rápido. Os dedos dele procuram você por trás." },
            ["e.Shurale.defense"] = new[] {
                "Iron, up close. It only moves when you look away: turn away, let it come near — then turn sharply and strike.",
                "Железо, вплотную. Он движется, только когда на него не смотрят: отвернись, дай подойти — потом резко повернись и бей.",
                "Темір, таяп келгенде. Оған қарамағанда ғана қозғалады: теріс қара, жақындасын — сосын кенет бұрылып, ұр.",
                "Hierro, de cerca. Solo se mueve cuando no lo miras: aparta la vista, deja que se acerque y luego gírate de golpe y golpea.",
                "Ferro, de perto. Só se move quando você não olha: desvie o olhar, deixe-o chegar — depois vire de repente e golpeie." },
            ["e.Shurale.hint"] = new[] {
                "It's a shurale. It fears iron. Look away so it comes closer, then turn and double-tap the screen.",
                "Это шурале. Он боится железа. Отвернись, чтобы он подошёл, потом повернись и коснись экрана дважды.",
                "Бұл — шүрәле. Ол темірден қорқады. Жақындасын деп теріс қара, сосын бұрылып, экранды екі рет түрт.",
                "Es un shurale. Teme el hierro. Aparta la vista para que se acerque, luego gírate y toca la pantalla dos veces.",
                "É um shurale. Ele teme ferro. Desvie o olhar para ele se aproximar, depois vire e toque duas vezes na tela." },
            ["e.Shurale.lair"] = new[] {
                "Behind your back — the way it follows a traveller through the forest.",
                "За спиной — так он идёт за путником по лесу.",
                "Арқаңда — ол орманда жолаушының соңынан осылай ереді.",
                "A tu espalda: así sigue al viajero por el bosque.",
                "Atrás de você — é assim que ele segue o viajante pela floresta." },
            ["e.Shurale.tale"] = new[] {
                "\"What is your name?\" asked the shurale. \"Byltyr — Last Year,\" answered the woodcutter, and drove the iron wedge out. The shurale screamed with its fingers caught, and the other spirits asked who had hurt it. \"Last Year!\" it howled. \"Then why are you shouting now?\" they laughed — and left it there until morning.",
                "«Как тебя зовут?» — спросил шурале. «Былтыр — Прошлогодний», — ответил дровосек и выбил железный клин. Шурале закричал, зажатый за пальцы, и другие духи спросили, кто его обидел. «Прошлогодний!» — выл он. «Чего ж ты кричишь сейчас?» — засмеялись они и оставили его там до утра.",
                "«Атың кім?» — деп сұрады шүрәле. «Былтыр», — деп жауап берді отыншы да, темір сынаны қағып алды. Саусағы қысылған шүрәле айқайлады, басқа рухтар оны кім ренжіткенін сұрады. «Былтыр!» — деп ұлыды ол. «Онда неге қазір айқайлайсың?» — деп күлді олар да, оны таңға дейін сол жерде қалдырды.",
                "«¿Cómo te llamas?», preguntó el shurale. «Byltyr, el Año Pasado», respondió el leñador, y sacó la cuña de hierro. El shurale gritó con los dedos atrapados, y los otros espíritus preguntaron quién le había hecho daño. «¡El Año Pasado!», aulló. «Entonces, ¿por qué gritas ahora?», se rieron, y lo dejaron allí hasta la mañana.",
                "\"Como você se chama?\" perguntou o shurale. \"Byltyr — Ano Passado\", respondeu o lenhador, e arrancou a cunha de ferro. O shurale gritou com os dedos presos, e os outros espíritos perguntaram quem o tinha machucado. \"O Ano Passado!\", uivou. \"Então por que grita agora?\", riram eles — e o deixaram lá até de manhã." },
            ["e.Ubyr.name"] = new[] { "Ubyr", "Убыр", "Обыр", "Ubyr", "Ubyr" },
            ["e.Ubyr.origin"] = new[] { "Tatar and Bashkir folklore", "Татарский и башкирский фольклор", "Татар және башқұрт фольклоры", "Folclore tártaro y baskir", "Folclore tártaro e bashkir" },
            ["e.Ubyr.lore"] = new[] {
                "The hungry spirit of a dead witch. At night it leaves the grave as a ball of fire or a whirl of sparks, circles over houses and drinks the blood and strength of sleepers. In the village they knew: wherever it touched down, salt had to be thrown — salt puts out its fire, and it flies back to the grave.",
                "Голодный дух умершей ведьмы. Ночью выходит из могилы огненным шаром или вихрем искр, кружит над домами и пьёт кровь и силы спящих. В деревне знали: где он опустился, туда надо бросить соль — соль гасит его огонь, и он улетает обратно в могилу.",
                "Өлген мыстанның аш рухы. Түнде көрден от шар не ұшқын құйыны болып шығып, үйлердің үстінде айналып, ұйықтағандардың қаны мен күшін сорады. Ауылда білетін: ол қай жерге қонса, сол жерге тұз шашу керек — тұз оның отын сөндіреді де, ол көріне қайта ұшып кетеді.",
                "El espíritu hambriento de una bruja muerta. De noche sale de la tumba como una bola de fuego o un remolino de chispas, gira sobre las casas y bebe la sangre y la fuerza de los que duermen. En el pueblo sabían: donde bajaba, había que echar sal; la sal apaga su fuego y vuelve volando a la tumba.",
                "O espírito faminto de uma bruxa morta. À noite sai da cova como uma bola de fogo ou um redemoinho de faíscas, gira sobre as casas e bebe o sangue e a força de quem dorme. Na aldeia sabiam: onde ele descesse, era preciso jogar sal — o sal apaga o fogo dele, e ele volta voando para a cova." },
            ["e.Ubyr.signs"] = new[] {
                "The crackle of fire, a hiss. A burning ball circles around you, tighter with every turn — don't let it close the ring.",
                "Треск огня, шипение. Огненный шар кружит вокруг тебя, с каждым кругом теснее — не дай ему замкнуть кольцо.",
                "Оттың шытырлауы, ысылдау. От шар айналаңда айналып, әр айналған сайын тарыла түседі — сақинаны тұйықтауға жол берме.",
                "Crepitar de fuego, un siseo. Una bola ardiente gira a tu alrededor, más cerca a cada vuelta: no dejes que cierre el círculo.",
                "Estalar de fogo, um chiado. Uma bola em chamas gira ao seu redor, mais perto a cada volta — não deixe que feche o círculo." },
            ["e.Ubyr.defense"] = new[] {
                "Salt. Catch it in your sight as it circles — and throw.",
                "Соль. Поймай его взглядом на круге — и бросай.",
                "Тұз. Айналып жүргенде көзіңмен іліп ал — сосын лақтыр.",
                "Sal. Atrápalo con la mirada mientras gira y lanza.",
                "Sal. Pegue-o com o olhar enquanto gira — e jogue." },
            ["e.Ubyr.hint"] = new[] {
                "It's an ubyr. It fears salt: follow it with your eyes and swipe up.",
                "Это убыр. Он боится соли: проследи за ним взглядом и смахни пальцем вверх.",
                "Бұл — обыр. Ол тұздан қорқады: оны көзіңмен бақылап, саусақпен жоғары сырғыт.",
                "Es un ubyr. Teme la sal: síguelo con la mirada y desliza hacia arriba.",
                "É um ubyr. Ele teme sal: siga-o com o olhar e deslize para cima." },
            ["e.Ubyr.lair"] = new[] {
                "High up, under the ceiling — the way it hangs over a roof before it comes down.",
                "Высоко, под потолком — так он висит над крышей, прежде чем опуститься.",
                "Жоғарыда, төбенің астында — ол түсер алдында шатырдың үстінде осылай ілініп тұрады.",
                "Arriba, bajo el techo: así se cierne sobre el tejado antes de bajar.",
                "No alto, sob o teto — é assim que ele paira sobre o telhado antes de descer." },
            ["e.Ubyr.tale"] = new[] {
                "In a Bashkir village people began to wake up pale and weak, one house after another. An old man sat up on the roof all night and saw it: a ball of fire rolled out of the old cemetery and dropped into a chimney. He climbed down and poured a whole sack of salt down that chimney. In the morning the grave of the miller's widow was found open, and the earth around it was scorched.",
                "В башкирской деревне люди начали просыпаться бледными и слабыми — дом за домом. Один старик просидел ночь на крыше и увидел: из старого кладбища выкатился огненный шар и упал в печную трубу. Старик слез и высыпал в эту трубу целый мешок соли. Утром нашли разрытой могилу мельниковой вдовы, а земля вокруг была выжжена.",
                "Бір башқұрт ауылында адамдар үй-үйімен бозарып, әлсіреп ояна бастады. Бір шал түні бойы шатырда отырып көрді: ескі зираттан от шар домалап шығып, мұржаға түсті. Шал түсіп, сол мұржаға бір қап тұз төкті. Таңертең диірменші жесірінің көрі ашылып жатқанын тапты, айналасындағы жер күйіп кеткен еді.",
                "En una aldea baskir la gente empezó a despertarse pálida y débil, casa tras casa. Un anciano pasó la noche en el tejado y lo vio: una bola de fuego salió rodando del viejo cementerio y cayó por una chimenea. Bajó y vació un saco entero de sal por esa chimenea. Por la mañana encontraron abierta la tumba de la viuda del molinero, y la tierra alrededor estaba chamuscada.",
                "Numa aldeia bashkir as pessoas começaram a acordar pálidas e fracas, casa após casa. Um velho passou a noite no telhado e viu: uma bola de fogo saiu rolando do velho cemitério e caiu numa chaminé. Ele desceu e despejou um saco inteiro de sal naquela chaminé. De manhã encontraram aberta a cova da viúva do moleiro, e a terra em volta estava queimada." },
            ["e.ZhalmauyzKempir.name"] = new[] { "Zhalmauyz Kempir", "Жалмауыз-кемпир", "Жалмауыз кемпір", "Zhalmauyz Kempir", "Zhalmauyz Kempir" },
            ["e.ZhalmauyzKempir.origin"] = new[] { "Kazakh folklore", "Казахский фольклор", "Қазақ фольклоры", "Folclore kazajo", "Folclore cazaque" },
            ["e.ZhalmauyzKempir.lore"] = new[] {
                "The cannibal crone of Kazakh tales, with seven heads that each speak and chew at once. She lives in a lonely yurt in the steppe, pretends to be a kind grandmother and offers a night's rest to anyone lost. In every tale she is beaten the same way — with fire: a burning brand, a torch, light thrown into her many faces.",
                "Старуха-людоедка из казахских сказок, у которой семь голов, и каждая говорит и жуёт сама по себе. Живёт в одинокой юрте в степи, притворяется доброй бабушкой и предлагает ночлег заблудившимся. Во всех сказках её побеждают одним — огнём: горящей головнёй, факелом, светом в её многие лица.",
                "Қазақ ертегілеріндегі адам жейтін кемпір, жеті басы бар, әрқайсысы өз бетінше сөйлеп, шайнайды. Далада жалғыз киіз үйде тұрады, мейірімді әжесі болып көрініп, адасқандарға түнеуге орын ұсынады. Барлық ертегіде оны бір нәрсемен жеңеді — отпен: жанған шоқпен, алаумен, оның көп бетіне түскен жарықпен.",
                "La vieja caníbal de los cuentos kazajos, con siete cabezas que hablan y mastican cada una por su cuenta. Vive en una yurta solitaria en la estepa, se hace pasar por una abuela bondadosa y ofrece posada a los perdidos. En todos los cuentos la vencen igual: con fuego, un tizón, una antorcha, luz en sus muchas caras.",
                "A velha canibal dos contos cazaques, de sete cabeças que falam e mastigam cada uma por si. Vive numa iurta solitária na estepe, finge ser uma avó bondosa e oferece pouso a quem se perde. Em todos os contos ela é vencida do mesmo jeito — com fogo: um tição, uma tocha, luz nas suas muitas caras." },
            ["e.ZhalmauyzKempir.signs"] = new[] {
                "Many voices muttering at once, the snap of jaws. She walks toward you steadily — and stops dead in the light.",
                "Множество голосов бормочут наперебой, щёлкают челюсти. Идёт к тебе ровно — и замирает на свету.",
                "Көп дауыс қатар күбірлейді, жақтар шартылдайды. Саған біркелкі жүріп келеді — жарықта қатып қалады.",
                "Muchas voces murmurando a la vez, el chasquido de mandíbulas. Camina hacia ti sin parar y se congela con la luz.",
                "Muitas vozes murmurando ao mesmo tempo, o estalo de mandíbulas. Ela anda até você sem parar — e congela na luz." },
            ["e.ZhalmauyzKempir.defense"] = new[] {
                "The lantern. Keep the light on her faces until she burns away.",
                "Фонарь. Держи свет на её лицах, пока она не сгорит.",
                "Шам. Ол жанып біткенше жарықты беттерінен түсірме.",
                "La linterna. Mantén la luz sobre sus caras hasta que se consuma.",
                "A lanterna. Mantenha a luz nas caras dela até que se consuma." },
            ["e.ZhalmauyzKempir.hint"] = new[] {
                "It's Zhalmauyz Kempir. She fears fire: hold your finger — the lantern — and keep her in the beam.",
                "Это Жалмауыз-кемпир. Она боится огня: зажми палец — фонарь — и держи её в луче.",
                "Бұл — Жалмауыз кемпір. Ол оттан қорқады: саусағыңды басып тұр — шам жанады — және оны сәуледе ұста.",
                "Es Zhalmauyz Kempir. Teme el fuego: mantén el dedo pulsado (la linterna) y no la saques del haz.",
                "É Zhalmauyz Kempir. Ela teme fogo: segure o dedo (a lanterna) e mantenha-a no feixe." },
            ["e.ZhalmauyzKempir.lair"] = new[] {
                "In the darkest corner — the back of a yurt, where the fire does not reach.",
                "В самом тёмном углу — в глубине юрты, куда не достаёт огонь.",
                "Ең қараңғы бұрышта — киіз үйдің төрінде, от жетпейтін жерде.",
                "En el rincón más oscuro: al fondo de una yurta, donde no llega el fuego.",
                "No canto mais escuro — no fundo de uma iurta, onde o fogo não alcança." },
            ["e.ZhalmauyzKempir.tale"] = new[] {
                "Two brothers lost their way in a snowstorm and came to a yurt where a kind old woman gave them meat broth. The younger one noticed she had too many shadows on the wall. At night he heard seven voices whispering over the elder brother's bed, deciding who would eat first. He pulled a brand from the hearth and pushed it into the dark — and seven faces screamed at once.",
                "Двое братьев заблудились в буране и вышли к юрте, где добрая старушка накормила их бульоном. Младший заметил: теней на стене у неё слишком много. Ночью он услышал, как над постелью старшего шепчутся семь голосов, решая, кто будет есть первым. Он выхватил из очага головню и ткнул в темноту — и семь лиц закричали разом.",
                "Екі ағайынды боранда адасып, киіз үйге шықты, онда мейірімді кемпір оларға сорпа берді. Інісі байқады: оның қабырғадағы көлеңкелері тым көп. Түнде ол ағасының төсегінің үстінде жеті дауыстың кім бірінші жейтінін сыбырласып шешіп жатқанын естіді. Ол ошақтан шоқ суырып алып, қараңғыға сұқты — жеті бет бірден айқайлады.",
                "Dos hermanos se perdieron en una ventisca y llegaron a una yurta donde una anciana amable les dio caldo. El menor notó que en la pared había demasiadas sombras. De noche oyó siete voces susurrando sobre la cama del mayor, decidiendo quién comería primero. Sacó un tizón del hogar y lo hundió en la oscuridad, y siete caras gritaron a la vez.",
                "Dois irmãos se perderam numa nevasca e chegaram a uma iurta onde uma velhinha gentil lhes deu caldo. O mais novo notou que havia sombras demais na parede. À noite ouviu sete vozes cochichando sobre a cama do mais velho, decidindo quem comeria primeiro. Ele puxou um tição da lareira e o enfiou no escuro — e sete caras gritaram de uma vez." },
            ["e.Karakoncolos.name"] = new[] { "Karakoncolos", "Каракончолос", "Қаракоңқыл", "Karakoncolos", "Karakoncolos" },
            ["e.Karakoncolos.origin"] = new[] { "Turkish and Balkan folklore", "Турецкий и балканский фольклор", "Түрік және Балқан фольклоры", "Folclore turco y balcánico", "Folclore turco e balcânico" },
            ["e.Karakoncolos.lore"] = new[] {
                "A huge hairy creature of the coldest days of winter, the \"zemheri\". It stands outside in the dark and calls people by name in the voice of someone dear. Whoever answers and steps out freezes where they stand. It is afraid of the sound of bells: in the villages they hung bells on the gates during the cold nights.",
                "Огромное косматое существо самых лютых зимних дней — «земхери». Стоит снаружи в темноте и зовёт людей по имени голосом кого-то родного. Кто отзовётся и выйдет — замерзает на месте. Боится колокольного звона: в деревнях в морозные ночи вешали на ворота колокольчики.",
                "Қыстың ең қатты күндерінің — «земхеридің» алып түкті мақұлығы. Сыртта қараңғыда тұрып, адамдарды жақын біреудің даусымен атынан шақырады. Жауап беріп шыққан адам сол жерде қатып қалады. Қоңырау үнінен қорқады: ауылдарда аязды түндері қақпаларға қоңырау ілген.",
                "Una enorme criatura peluda de los días más fríos del invierno, el «zemheri». Se queda afuera en la oscuridad y llama a la gente por su nombre con la voz de un ser querido. Quien responde y sale se congela donde está. Le temen las campanas: en los pueblos, en las noches de helada, colgaban campanillas en las puertas.",
                "Uma enorme criatura peluda dos dias mais frios do inverno, o \"zemheri\". Fica lá fora no escuro e chama as pessoas pelo nome com a voz de alguém querido. Quem responde e sai congela onde está. Tem medo do som de sinos: nas aldeias, nas noites de geada, penduravam sinos nos portões." },
            ["e.Karakoncolos.signs"] = new[] {
                "Icy wind; someone calling your name from far away, in a familiar voice. It fades and appears closer each time.",
                "Ледяной ветер; кто-то издалека зовёт тебя по имени знакомым голосом. Тает и возникает каждый раз ближе.",
                "Мұздай жел; біреу алыстан таныс даусымен сені атыңнан шақырады. Еріп жоғалып, әр жолы жақынырақ пайда болады.",
                "Viento helado; alguien te llama por tu nombre desde lejos con una voz conocida. Se desvanece y aparece cada vez más cerca.",
                "Vento gelado; alguém chama seu nome de longe com uma voz conhecida. Some e reaparece cada vez mais perto." },
            ["e.Karakoncolos.defense"] = new[] {
                "A bell. Face it and ring — never answer its call.",
                "Колокольчик. Повернись к нему и звони — и никогда не отвечай на зов.",
                "Қоңырау. Оған бұрылып, шылдырлат — шақыруына ешқашан жауап берме.",
                "Una campanilla. Míralo de frente y hazla sonar, y nunca respondas a su llamada.",
                "Um sino. Fique de frente para ele e toque — e nunca responda ao chamado." },
            ["e.Karakoncolos.hint"] = new[] {
                "It's a karakoncolos. It fears the bell: face it and shake the phone. Don't answer when it calls!",
                "Это каракончолос. Он боится колокольчика: повернись к нему и встряхни телефон. Не отвечай на зов!",
                "Бұл — қаракоңқыл. Ол қоңыраудан қорқады: оған бұрылып, телефонды сілкіле. Шақырғанда жауап берме!",
                "Es un karakoncolos. Teme la campanilla: míralo de frente y agita el teléfono. ¡No respondas cuando llame!",
                "É um karakoncolos. Ele teme o sino: fique de frente para ele e chacoalhe o celular. Não responda quando ele chamar!" },
            ["e.Karakoncolos.lair"] = new[] {
                "Far away, by a window or a door — on the other side of the threshold, in the cold.",
                "Далеко, у окна или двери — по ту сторону порога, на холоде.",
                "Алыста, терезе не есік жанында — табалдырықтың арғы жағында, суықта.",
                "Lejos, junto a una ventana o una puerta: al otro lado del umbral, en el frío.",
                "Longe, perto de uma janela ou porta — do outro lado da soleira, no frio." },
            ["e.Karakoncolos.tale"] = new[] {
                "In the mountains of Anatolia a shepherd's wife heard her husband calling from the yard on the coldest night of the year: \"Open up, I'm freezing!\" But her husband had been asleep beside her for an hour. She did not answer — she only rang the cow's bell until dawn. In the morning there were tracks in the snow around the house: big, bare, and not human.",
                "В горах Анатолии жена пастуха в самую холодную ночь года услышала со двора голос мужа: «Открой, я замерзаю!» Но муж уже час спал рядом с ней. Она не ответила — только до рассвета звонила в коровий колокольчик. Утром вокруг дома на снегу нашли следы: большие, босые и не человеческие.",
                "Анадолы тауларында бір малшының әйелі жылдың ең суық түнінде ауладан күйеуінің даусын естіді: «Аш, мен тоңып барамын!» Бірақ күйеуі оның жанында бір сағаттан бері ұйықтап жатқан еді. Ол жауап бермеді — тек таң атқанша сиырдың қоңырауын шылдырлатты. Таңертең үйдің айналасындағы қардан із тапты: үлкен, жалаң аяқ, адамдікі емес.",
                "En las montañas de Anatolia, la mujer de un pastor oyó en la noche más fría del año la voz de su marido desde el patio: «¡Abre, me estoy congelando!». Pero su marido llevaba una hora dormido a su lado. No respondió: solo tocó la campanilla de la vaca hasta el amanecer. Por la mañana había huellas en la nieve alrededor de la casa: grandes, descalzas y no humanas.",
                "Nas montanhas da Anatólia, a mulher de um pastor ouviu, na noite mais fria do ano, a voz do marido no quintal: \"Abra, estou congelando!\" Mas o marido dormia ao lado dela havia uma hora. Ela não respondeu — só tocou o sino da vaca até o amanhecer. De manhã havia pegadas na neve em volta da casa: grandes, descalças e não humanas." },
            ["e.Abaasy.name"] = new[] { "Abaasy", "Абаасы", "Абаасы", "Abaasy", "Abaasy" },
            ["e.Abaasy.origin"] = new[] { "Yakut (Sakha) folklore", "Якутский фольклор", "Якут (саха) фольклоры", "Folclore yakuto (sajá)", "Folclore iacuto (sakha)" },
            ["e.Abaasy.lore"] = new[] {
                "A demon of the lower world from Yakut epics: one eye in the middle of its forehead, one arm growing from its chest, one leg, and teeth of iron. It hops out of the dark and steals the souls of people and cattle. Shamans drove the abaasy away with the smoke of juniper and bitter herbs — its single eye cannot bear the smoke.",
                "Демон нижнего мира из якутских олонхо: один глаз посреди лба, одна рука, растущая из груди, одна нога и железные зубы. Выпрыгивает из темноты и похищает души людей и скота. Шаманы отгоняли абаасы дымом можжевельника и горьких трав — его единственный глаз не выносит дыма.",
                "Якут олоңхосындағы төменгі әлемнің жыны: маңдайының ортасында бір көзі, кеудесінен өскен бір қолы, бір аяғы және темір тістері бар. Қараңғыдан секіріп шығып, адамдар мен малдың жанын ұрлайды. Бақсылар абаасыны арша мен ащы шөптердің түтінімен қуған — оның жалғыз көзі түтінге шыдамайды.",
                "Un demonio del mundo inferior de las epopeyas yakutas: un solo ojo en medio de la frente, un solo brazo que le sale del pecho, una sola pierna y dientes de hierro. Salta desde la oscuridad y roba las almas de personas y ganado. Los chamanes lo ahuyentaban con humo de enebro y hierbas amargas: su único ojo no soporta el humo.",
                "Um demônio do mundo inferior das epopeias iacutas: um só olho no meio da testa, um só braço saindo do peito, uma só perna e dentes de ferro. Salta da escuridão e rouba as almas de pessoas e do gado. Os xamãs o expulsavam com fumaça de zimbro e ervas amargas — o único olho dele não suporta a fumaça." },
            ["e.Abaasy.signs"] = new[] {
                "The grinding of iron teeth, the twang of a jaw harp somewhere in the dark. It stands still — then hops at you on its single leg in heavy bounds.",
                "Скрежет железных зубов, где-то в темноте звенит хомус. Стоит неподвижно — и тяжёлыми скачками прыгает к тебе на единственной ноге.",
                "Темір тістердің шиқылы, қараңғыда бір жерде хомус шыңылдайды. Қимылсыз тұрады да — жалғыз аяғымен ауыр секіріп саған келеді.",
                "El rechinar de dientes de hierro, el zumbido de un arpa de boca en la oscuridad. Se queda quieto y luego salta hacia ti a grandes brincos sobre su única pierna.",
                "O ranger de dentes de ferro, o zumbido de um berimbau de boca no escuro. Fica parado — e salta até você em pulos pesados na sua única perna." },
            ["e.Abaasy.defense"] = new[] {
                "Wormwood — bitter smoke. Wave the bunch right into its single eye.",
                "Полынь — горький дым. Взмахни пучком прямо в его единственный глаз.",
                "Жусан — ащы түтін. Шоқты тура оның жалғыз көзіне қарай сілте.",
                "Ajenjo: humo amargo. Agita el manojo justo hacia su único ojo.",
                "Losna — fumaça amarga. Agite o maço bem na direção do único olho dele." },
            ["e.Abaasy.hint"] = new[] {
                "It's an abaasy. It fears bitter smoke: look at it and zigzag your finger left and right.",
                "Это абаасы. Он боится горького дыма: посмотри на него и проведи пальцем зигзагом влево-вправо.",
                "Бұл — абаасы. Ол ащы түтіннен қорқады: оған қарап, саусағыңды солға-оңға ирек етіп жүргіз.",
                "Es un abaasy. Teme el humo amargo: míralo y haz un zigzag con el dedo a izquierda y derecha.",
                "É um abaasy. Ele teme fumaça amarga: olhe para ele e faça um zigue-zague com o dedo para os lados." },
            ["e.Abaasy.lair"] = new[] {
                "In the darkest corner, low — like a crack leading down into the lower world.",
                "В самом тёмном углу, низко — как трещина, ведущая в нижний мир.",
                "Ең қараңғы бұрышта, төменде — төменгі әлемге апаратын жарық сияқты.",
                "En el rincón más oscuro, abajo: como una grieta que lleva al mundo inferior.",
                "No canto mais escuro, embaixo — como uma fenda que leva ao mundo inferior." },
            ["e.Abaasy.tale"] = new[] {
                "In an olonkho it is told how an abaasy stole a bride from her own wedding: it hopped in on one leg in the middle of the feast, and the guests could not move for fear of its single eye. Only the old shaman woman did not lose her head: she threw a whole armful of juniper into the fire. The smoke filled the yurt, the demon howled, rubbing its eye — and the bride slipped out of its iron grip.",
                "В олонхо рассказывается, как абаасы похитил невесту прямо со свадьбы: вприпрыжку на одной ноге ворвался посреди пира, и гости не могли пошевелиться от страха перед его единственным глазом. Только старая шаманка не растерялась: бросила в огонь целую охапку можжевельника. Дым заполнил юрту, демон взвыл, протирая глаз, — и невеста выскользнула из его железной хватки.",
                "Олоңхода абаасының қалыңдықты тура тойдан ұрлап әкеткені айтылады: тойдың ортасында бір аяғымен секіріп кіріп келді, қонақтар оның жалғыз көзінен қорқып, қимылдай алмады. Тек кәрі бақсы әйел сасқан жоқ: отқа бір құшақ арша тастады. Түтін киіз үйді толтырды, жын көзін уқалап ұлыды — қалыңдық оның темір құрсауынан сытылып шықты.",
                "En un olonjó se cuenta cómo un abaasy robó a una novia en plena boda: entró a saltos sobre una pierna en mitad del banquete, y los invitados no podían moverse del miedo a su único ojo. Solo la vieja chamana no perdió la calma: echó al fuego un brazado entero de enebro. El humo llenó la yurta, el demonio aulló frotándose el ojo, y la novia se escurrió de su garra de hierro.",
                "Num olonkho conta-se como um abaasy roubou uma noiva em pleno casamento: entrou pulando numa perna só no meio da festa, e os convidados não conseguiam se mexer de medo do seu único olho. Só a velha xamã não perdeu a cabeça: jogou no fogo uma braçada inteira de zimbro. A fumaça encheu a iurta, o demônio uivou esfregando o olho — e a noiva escapou da garra de ferro dele." },
            ["e.BabaYaga.name"] = new[] { "Baba Yaga", "Баба-яга", "Баба-яга", "Baba Yaga", "Baba Yaga" },
            ["e.BabaYaga.origin"] = new[] { "Slavic folklore", "Славянский фольклор", "Славян фольклоры", "Folclore eslavo", "Folclore eslavo" },
            ["e.BabaYaga.lore"] = new[] {
                "The bony-legged witch of the forest who flies in a mortar, steering with a pestle and sweeping away her tracks with a broom. Her teeth are iron, her nose grows into the ceiling, and her hut stands on chicken legs. She eats those who come to her with nothing — but a guest who has shared bread and salt she may not touch. Salt binds her.",
                "Костяная нога, лесная ведьма, что летает в ступе, правит пестом и метлой заметает след. Зубы у неё железные, нос в потолок врос, изба на курьих ножках. Тех, кто пришёл с пустыми руками, она съедает — но гостя, с которым делила хлеб-соль, тронуть не смеет. Соль её связывает.",
                "Сүйек аяқ, орман мыстаны: келіге мініп ұшады, келсапмен басқарады, ізін сыпырғышпен сыпырады. Тістері темір, мұрны төбеге жабысқан, лашығы тауық аяқтарының үстінде тұр. Құр қол келгендерді жейді — бірақ нан-тұзын бөліскен қонаққа тиісе алмайды. Тұз оны байлайды.",
                "La bruja del bosque de pierna huesuda que vuela en un mortero, se guía con la mano del mortero y barre sus huellas con una escoba. Tiene dientes de hierro, la nariz le crece hasta el techo y su choza se alza sobre patas de gallina. Se come a los que llegan con las manos vacías, pero al huésped con quien ha compartido pan y sal no puede tocarlo. La sal la ata.",
                "A bruxa da floresta de perna de osso, que voa num pilão, guia-se com a mão de pilão e varre o próprio rastro com uma vassoura. Tem dentes de ferro, o nariz cresce até o teto e sua cabana fica sobre pés de galinha. Devora quem chega de mãos vazias — mas o hóspede com quem dividiu pão e sal ela não pode tocar. O sal a prende." },
            ["e.BabaYaga.signs"] = new[] {
                "The thud of a mortar, the swish of a broom, a crone's cackle. She comes at you steadily and does not stop.",
                "Стук ступы, шорох метлы, старушечий хохот. Идёт на тебя ровно и не останавливается.",
                "Келінің дүңкілі, сыпырғыштың сыбдыры, кемпірдің қарқылы. Саған біркелкі келе береді, тоқтамайды.",
                "El golpe de un mortero, el roce de una escoba, la carcajada de una vieja. Viene hacia ti sin parar.",
                "A batida de um pilão, o roçar de uma vassoura, a gargalhada de uma velha. Vem até você sem parar." },
            ["e.BabaYaga.defense"] = new[] {
                "Salt — like bread and salt offered to a guest. Throw it right at her.",
                "Соль — как хлеб-соль гостю. Брось её прямо в неё.",
                "Тұз — қонаққа ұсынылған нан-тұздай. Оны тура соған лақтыр.",
                "Sal, como el pan y la sal que se ofrecen al huésped. Lánzasela directamente.",
                "Sal — como o pão e sal oferecidos ao hóspede. Jogue direto nela." },
            ["e.BabaYaga.hint"] = new[] {
                "It's Baba Yaga. She fears salt: look at her and swipe up.",
                "Это Баба-яга. Она боится соли: посмотри на неё и смахни пальцем вверх.",
                "Бұл — Баба-яга. Ол тұздан қорқады: оған қарап, саусақпен жоғары сырғыт.",
                "Es Baba Yaga. Teme la sal: mírala y desliza hacia arriba.",
                "É Baba Yaga. Ela teme sal: olhe para ela e deslize para cima." },
            ["e.BabaYaga.lair"] = new[] {
                "Behind your back — \"hut, hut, turn your back to the forest and your front to me.\"",
                "За спиной — «избушка, избушка, стань к лесу задом, ко мне передом».",
                "Арқаңда — «лашық, лашық, орманға арқаңмен, маған бетіңмен тұр».",
                "A tu espalda: «choza, choza, ponte de espaldas al bosque y de frente a mí».",
                "Atrás de você — \"cabana, cabana, vire as costas para a floresta e a frente para mim\"." },
            ["e.BabaYaga.tale"] = new[] {
                "Vasilisa was sent to Baba Yaga for fire and came back alive: she did what she was told, kept her doll's advice, and did not ask about the hands that came out of the walls. The skull with burning eyes that Yaga gave her lit her way home — and by morning it had burned her cruel stepmother to ash. Yaga keeps her word. She simply never says what it will cost.",
                "Василису послали к Бабе-яге за огнём, и она вернулась живой: делала, что велено, слушалась куколку и не спрашивала про руки, что выходили из стен. Череп с горящими глазами, что дала ей Яга, освещал путь домой — а к утру сжёг злую мачеху дотла. Яга держит слово. Просто никогда не говорит, чего оно будет стоить.",
                "Василисаны Баба-ягаға от алуға жіберді, ол тірі оралды: айтқанын істеді, қуыршағын тыңдады, қабырғадан шыққан қолдар туралы сұрамады. Яга берген, көздері жанған бас сүйек оның үйге жолын жарықтандырды — ал таңға қарай зұлым өгей шешесін күл етіп өртеп жіберді. Яга сөзінде тұрады. Тек оның қаншаға түсетінін ешқашан айтпайды.",
                "A Vasilisa la mandaron a casa de Baba Yaga a buscar fuego, y volvió viva: hizo lo que le mandaron, escuchó a su muñeca y no preguntó por las manos que salían de las paredes. La calavera de ojos ardientes que le dio Yaga le alumbró el camino a casa… y al amanecer redujo a cenizas a su cruel madrastra. Yaga cumple su palabra. Solo nunca dice lo que costará.",
                "Mandaram Vasilisa à casa de Baba Yaga buscar fogo, e ela voltou viva: fez o que mandaram, ouviu a bonequinha e não perguntou sobre as mãos que saíam das paredes. A caveira de olhos em brasa que Yaga lhe deu iluminou o caminho de casa — e de manhã reduziu a cinzas a madrasta cruel. Yaga cumpre a palavra. Só nunca diz quanto vai custar." },
            ["e.Strigoi.name"] = new[] { "Strigoi", "Стригой", "Стригой", "Strigoi", "Strigoi" },
            ["e.Strigoi.origin"] = new[] { "Romanian folklore", "Румынский фольклор", "Румын фольклоры", "Folclore rumano", "Folclore romeno" },
            ["e.Strigoi.lore"] = new[] {
                "The restless dead of Romania: a man who rises from the grave with red hair, blue eyes and two hearts, and comes back to his own family first. He drinks their strength night by night. Villagers smeared garlic and bitter herbs on doors, windows and chimneys — the strigoi cannot pass through the smell.",
                "Неупокоенный мертвец Румынии: встаёт из могилы рыжий, голубоглазый, с двумя сердцами — и первым делом возвращается к своей семье. Ночь за ночью пьёт их силы. В сёлах натирали чесноком и горькими травами двери, окна и дымоходы — сквозь этот запах стригой не проходит.",
                "Румынияның тыным таппаған өлігі: көрінен жирен шашты, көк көзді, екі жүректі болып тұрады — бірінші кезекте өз отбасына оралады. Түн сайын олардың күшін сорады. Ауылдарда есік, терезе және мұржаларды сарымсақ пен ащы шөптермен сылаған — стригой бұл иістен өте алмайды.",
                "El muerto sin descanso de Rumanía: se levanta de la tumba pelirrojo, de ojos azules y con dos corazones, y lo primero que hace es volver con su propia familia. Noche tras noche les bebe la fuerza. En los pueblos untaban ajo y hierbas amargas en puertas, ventanas y chimeneas: el strigoi no puede atravesar ese olor.",
                "O morto sem descanso da Romênia: levanta-se da cova ruivo, de olhos azuis e com dois corações — e antes de tudo volta para a própria família. Noite após noite bebe a força deles. Nas aldeias esfregavam alho e ervas amargas em portas, janelas e chaminés — o strigoi não passa por esse cheiro." },
            ["e.Strigoi.signs"] = new[] {
                "Wings beating in the dark, a hiss. It stands still — then lunges in sudden bursts.",
                "Хлопанье крыльев в темноте, шипение. Стоит неподвижно — и бросается внезапными рывками.",
                "Қараңғыдағы қанат сарт-сұрты, ысылдау. Қимылсыз тұрады да — кенет жұлқынып атылады.",
                "Aleteos en la oscuridad, un siseo. Se queda quieto y embiste con arranques repentinos.",
                "Asas batendo no escuro, um chiado. Fica parado — e investe em arrancadas súbitas." },
            ["e.Strigoi.defense"] = new[] {
                "Wormwood — garlic and bitter herbs. Wave the bunch at it.",
                "Полынь — чеснок и горькие травы. Взмахни пучком в его сторону.",
                "Жусан — сарымсақ пен ащы шөптер. Шоқты соған қарай сілте.",
                "Ajenjo: ajo y hierbas amargas. Agita el manojo hacia él.",
                "Losna — alho e ervas amargas. Agite o maço na direção dele." },
            ["e.Strigoi.hint"] = new[] {
                "It's a strigoi. It fears bitter herbs: look at it and zigzag your finger left and right.",
                "Это стригой. Он боится горьких трав: посмотри на него и проведи пальцем зигзагом влево-вправо.",
                "Бұл — стригой. Ол ащы шөптерден қорқады: оған қарап, саусағыңды солға-оңға ирек етіп жүргіз.",
                "Es un strigoi. Teme las hierbas amargas: míralo y haz un zigzag con el dedo a izquierda y derecha.",
                "É um strigoi. Ele teme ervas amargas: olhe para ele e faça um zigue-zague com o dedo para os lados." },
            ["e.Strigoi.lair"] = new[] {
                "Low, on the floor — the way he lies in the grave before he rises.",
                "Низко, на полу — так он лежит в могиле, прежде чем встать.",
                "Төменде, еденде — тұрар алдында көрде осылай жатады.",
                "Abajo, en el suelo: así yace en la tumba antes de levantarse.",
                "Embaixo, no chão — é assim que ele jaz na cova antes de se levantar." },
            ["e.Strigoi.tale"] = new[] {
                "In 2004, in a Romanian village, a family began to sicken after the death of their uncle. They were sure: he was coming back at night. They did what their grandparents had done — opened the grave, took out the heart, burned it and mixed the ashes with water. The family recovered. The police came. The village said: the police don't live here at night.",
                "В 2004 году в одной румынской деревне семья начала болеть после смерти дяди. Они были уверены: он возвращается по ночам. Сделали, как делали деды: вскрыли могилу, вынули сердце, сожгли и смешали пепел с водой. Семья поправилась. Приехала полиция. В деревне сказали: полиция здесь ночами не живёт.",
                "2004 жылы бір румын ауылында ағасы қайтыс болғаннан кейін бүкіл отбасы ауыра бастады. Олар сенімді болды: ол түнде оралып жүр. Аталары қалай істесе, солай істеді: көрді ашып, жүрегін алып, өртеп, күлін суға араластырды. Отбасы жазылды. Полиция келді. Ауылдағылар айтты: полиция мұнда түнде тұрмайды.",
                "En 2004, en una aldea rumana, una familia empezó a enfermar tras la muerte de su tío. Estaban seguros: volvía por las noches. Hicieron lo que hacían sus abuelos: abrieron la tumba, sacaron el corazón, lo quemaron y mezclaron la ceniza con agua. La familia se recuperó. Llegó la policía. En el pueblo dijeron: la policía no vive aquí de noche.",
                "Em 2004, numa aldeia romena, uma família começou a adoecer depois da morte do tio. Tinham certeza: ele voltava à noite. Fizeram o que faziam os avós: abriram a cova, tiraram o coração, queimaram e misturaram as cinzas com água. A família melhorou. A polícia veio. Na aldeia disseram: a polícia não mora aqui à noite." },
            ["e.BloodyMary.name"] = new[] { "Bloody Mary", "Кровавая Мэри", "Қанды Мэри", "Bloody Mary", "Bloody Mary" },
            ["e.BloodyMary.origin"] = new[] {
                "American and British urban legend",
                "Американская и британская городская легенда",
                "Америка мен Британия қалалық аңызы",
                "Leyenda urbana estadounidense y británica",
                "Lenda urbana americana e britânica" },
            ["e.BloodyMary.lore"] = new[] {
                "Say her name three times in front of a mirror in the dark — and she appears in the glass behind your reflection: a woman with a bleeding face who reaches out of the mirror. Older tellings say she was a girl who looked into the mirror at midnight to see her future husband and saw a skull instead. Show her another mirror, and she is pulled back into the glass.",
                "Скажи её имя трижды перед зеркалом в темноте — и она появится в стекле за твоим отражением: женщина с окровавленным лицом, что тянется из зеркала. Старые версии говорят: это девушка, которая в полночь гадала на суженого перед зеркалом и увидела череп. Покажи ей другое зеркало — и её затянет обратно в стекло.",
                "Қараңғыда айнаның алдында оның атын үш рет айт — ол айнада сенің бейнеңнің артында пайда болады: беті қанға боялған, айнадан қолын созған әйел. Ескі нұсқаларда айтылады: бұл түн ортасында айна алдында болашақ күйеуіне бал ашып, бас сүйекті көрген қыз. Оған басқа айнаны көрсет — оны қайтадан шыныға тартып әкетеді.",
                "Di su nombre tres veces frente a un espejo a oscuras y aparecerá en el cristal detrás de tu reflejo: una mujer con la cara ensangrentada que se estira fuera del espejo. Las versiones antiguas dicen que era una muchacha que se miró al espejo a medianoche para ver a su futuro marido y vio una calavera. Muéstrale otro espejo, y el cristal la arrastra de vuelta.",
                "Diga o nome dela três vezes diante de um espelho no escuro — e ela aparece no vidro atrás do seu reflexo: uma mulher de rosto ensanguentado que se estica para fora do espelho. As versões antigas dizem que era uma moça que olhou no espelho à meia-noite para ver o futuro marido e viu uma caveira. Mostre a ela outro espelho, e o vidro a puxa de volta." },
            ["e.BloodyMary.signs"] = new[] {
                "A name spoken three times through the static; glass cracking. Stare at her too long and she sinks into the reflection — and comes out closer, from another side.",
                "Сквозь помехи трижды звучит имя; трескается стекло. Если долго на неё смотреть, она уходит в отражение — и выходит ближе, с другой стороны.",
                "Кедергі арасынан ат үш рет естіледі; шыны шытынайды. Оған ұзақ қарасаң, ол шағылысқа кетіп қалады — басқа жақтан жақынырақ шығады.",
                "Un nombre pronunciado tres veces entre la estática; se raja un cristal. Si la miras demasiado, se hunde en el reflejo y sale más cerca, por otro lado.",
                "Um nome dito três vezes através da estática; um vidro trinca. Se você a encarar demais, ela some no reflexo — e sai mais perto, por outro lado." },
            ["e.BloodyMary.defense"] = new[] {
                "A mirror. Show her the glass — quickly, before she sinks.",
                "Зеркало. Покажи ей стекло — быстро, пока она не ушла в отражение.",
                "Айна. Оған шыныны көрсет — тез, ол шағылысқа кетпей тұрып.",
                "Un espejo. Muéstrale el cristal, rápido, antes de que se hunda.",
                "Um espelho. Mostre o vidro a ela — rápido, antes que afunde." },
            ["e.BloodyMary.hint"] = new[] {
                "It's Bloody Mary. She fears the mirror: glance at her and swipe down — don't stare.",
                "Это Кровавая Мэри. Она боится зеркала: взгляни на неё и смахни пальцем вниз — не смотри в упор.",
                "Бұл — Қанды Мэри. Ол айнадан қорқады: оған бір қарап, саусақпен төмен сырғыт — тесіле қарама.",
                "Es Bloody Mary. Teme el espejo: mírala un instante y desliza hacia abajo; no la mires fijamente.",
                "É Bloody Mary. Ela teme o espelho: olhe de relance e deslize para baixo — não encare." },
            ["e.BloodyMary.lair"] = new[] {
                "Where it's light and something reflects: a mirror, a window, a dark screen.",
                "Там, где светло и что-то отражает: зеркало, окно, тёмный экран.",
                "Жарық әрі бір нәрсе шағылысатын жерде: айна, терезе, қараңғы экран.",
                "Donde hay luz y algo refleja: un espejo, una ventana, una pantalla apagada.",
                "Onde há luz e algo reflete: um espelho, uma janela, uma tela apagada." },
            ["e.BloodyMary.tale"] = new[] {
                "At a sleepover in 1978 four girls locked themselves in a bathroom, turned off the light and said the name three times. Three of them saw nothing and laughed. The fourth said nothing at all. In the morning she wouldn't look into any mirror, and on the bathroom glass, from the inside, there were handprints — small, like a girl's.",
                "На ночёвке в 1978 году четыре девочки заперлись в ванной, выключили свет и трижды произнесли имя. Три ничего не увидели и смеялись. Четвёртая не сказала ни слова. Утром она не смотрела ни в одно зеркало, а на стекле в ванной изнутри остались отпечатки ладоней — маленьких, как у девочки.",
                "1978 жылы бір түнеуде төрт қыз жуынатын бөлмеге жабылып, жарықты сөндіріп, атты үш рет айтты. Үшеуі ештеңе көрмей, күлді. Төртіншісі бір ауыз сөз айтпады. Таңертең ол бірде-бір айнаға қарамады, ал жуынатын бөлмедегі шыныда ішкі жағынан алақан іздері қалды — қыздікіндей кішкентай.",
                "En una pijamada de 1978, cuatro niñas se encerraron en un baño, apagaron la luz y dijeron el nombre tres veces. Tres no vieron nada y se rieron. La cuarta no dijo ni una palabra. Por la mañana no quiso mirarse en ningún espejo, y en el cristal del baño, por dentro, había huellas de manos: pequeñas, como de niña.",
                "Numa festa do pijama em 1978, quatro meninas se trancaram no banheiro, apagaram a luz e disseram o nome três vezes. Três não viram nada e riram. A quarta não disse uma palavra. De manhã ela não olhava em nenhum espelho, e no vidro do banheiro, por dentro, havia marcas de mãos — pequenas, como de menina." },
            ["e.BellWitch.name"] = new[] { "The Bell Witch", "Ведьма Белла", "Белл мыстаны", "La Bruja de Bell", "A Bruxa de Bell" },
            ["e.BellWitch.origin"] = new[] { "Tennessee, USA, 1817", "Теннесси, США, 1817", "Теннесси, АҚШ, 1817", "Tennessee, EE. UU., 1817", "Tennessee, EUA, 1817" },
            ["e.BellWitch.lore"] = new[] {
                "The most famous haunting in America. On the Bell family farm, something invisible gnawed at the bedposts, pulled off the blankets, slapped the children and talked — in many voices, quoting sermons and singing hymns. It called itself \"Kate\". Church bells were the one thing that silenced it: when the bell rang, the voice in the house fell quiet.",
                "Самая известная история с призраком в Америке. На ферме семьи Белл что-то невидимое грызло столбики кроватей, срывало одеяла, давало пощёчины детям и говорило — многими голосами, цитируя проповеди и распевая гимны. Оно называло себя «Кейт». Заставить его замолчать мог только церковный колокол: когда он звонил, голос в доме стихал.",
                "Америкадағы ең атақты аруақ оқиғасы. Белл отбасының фермасында көзге көрінбейтін бір нәрсе төсек бағаналарын кеміріп, көрпелерді жұлып, балаларды шапалақтап, сөйлейтін — көп дауыспен, уағыздардан үзінді келтіріп, гимн айтып. Ол өзін «Кейт» деп атады. Оны тек шіркеу қоңырауы ғана тоқтата алатын: қоңырау соғылғанда, үйдегі дауыс басылатын.",
                "La aparición más famosa de Estados Unidos. En la granja de la familia Bell, algo invisible roía los postes de las camas, arrancaba las mantas, abofeteaba a los niños y hablaba con muchas voces, citando sermones y cantando himnos. Se hacía llamar «Kate». Solo la campana de la iglesia la hacía callar: cuando sonaba, la voz de la casa enmudecía.",
                "A assombração mais famosa dos Estados Unidos. Na fazenda da família Bell, algo invisível roía os pés das camas, arrancava os cobertores, dava tapas nas crianças e falava — com muitas vozes, citando sermões e cantando hinos. Chamava a si mesma de \"Kate\". Só o sino da igreja a calava: quando ele tocava, a voz na casa silenciava." },
            ["e.BellWitch.signs"] = new[] {
                "Invisible. An old woman's voice singing a hymn, the crack of a slap, things thrown across the room. After a few throws, it strikes.",
                "Невидима. Старушечий голос поёт гимн, звук пощёчины, вещи летят через комнату. После нескольких бросков — нападение.",
                "Көрінбейді. Кемпірдің даусы гимн айтады, шапалақтың дыбысы, заттар бөлмені кесіп ұшады. Бірнеше лақтырыстан кейін — шабуыл.",
                "Invisible. Una voz de anciana canta un himno, el chasquido de una bofetada, cosas que vuelan por la habitación. Tras varios lanzamientos, ataca.",
                "Invisível. Uma voz de velha canta um hino, o estalo de um tapa, coisas voando pelo quarto. Depois de alguns arremessos, ela ataca." },
            ["e.BellWitch.defense"] = new[] {
                "A bell. Turn toward the singing and ring until it stops.",
                "Колокольчик. Повернись туда, откуда поют, и звони, пока пение не стихнет.",
                "Қоңырау. Ән шыққан жаққа бұрылып, ән басылғанша шылдырлат.",
                "Una campanilla. Gírate hacia el canto y hazla sonar hasta que calle.",
                "Um sino. Vire-se para onde vem o canto e toque até ele parar." },
            ["e.BellWitch.hint"] = new[] {
                "It's the Bell Witch. She fears the bell: turn toward the noise and shake the phone.",
                "Это Ведьма Белла. Она боится колокольчика: повернись к шуму и встряхни телефон.",
                "Бұл — Белл мыстаны. Ол қоңыраудан қорқады: шуға қарай бұрылып, телефонды сілкіле.",
                "Es la Bruja de Bell. Teme la campanilla: gírate hacia el ruido y agita el teléfono.",
                "É a Bruxa de Bell. Ela teme o sino: vire-se para o barulho e chacoalhe o celular." },
            ["e.BellWitch.lair"] = new[] {
                "Close by, at the head of the bed — where the voice spoke to John Bell every night.",
                "Рядом, у изголовья — там, где голос каждую ночь говорил с Джоном Беллом.",
                "Жақын, бас жағында — дауыс күн сайын түнде Джон Беллмен сөйлескен жерде.",
                "Cerca, en la cabecera de la cama: donde la voz le hablaba a John Bell cada noche.",
                "Perto, na cabeceira da cama — onde a voz falava com John Bell toda noite." },
            ["e.BellWitch.tale"] = new[] {
                "In 1820 John Bell was found dying, and beside him a small vial of dark liquid. \"I gave Old Jack a big dose last night,\" said the voice from the ceiling, and laughed. At his funeral it sang a drinking song over the grave. Then it left, promising to return in seven years. People say it did — and that it is still waiting for someone to call it by name.",
                "В 1820 году Джона Белла нашли умирающим, а рядом — пузырёк с тёмной жидкостью. «Я дала старику Джеку хорошую дозу прошлой ночью», — сказал голос с потолка и засмеялся. На похоронах он пел над могилой застольную песню. Потом ушёл, обещая вернуться через семь лет. Говорят, вернулся — и до сих пор ждёт, когда его позовут по имени.",
                "1820 жылы Джон Беллді өліп жатқан күйінде тапты, жанында қара сұйықтығы бар шыны құты. «Кеше түнде кәрі Джекке жақсы мөлшер бердім», — деді төбеден шыққан дауыс та, күлді. Жерлеуде ол көрдің үстінде той әнін айтты. Сосын жеті жылдан кейін қайтып келемін деп кетті. Айтуларынша, қайтып келген — әлі күнге дейін біреудің оны атымен шақыруын күтеді.",
                "En 1820 encontraron a John Bell agonizando, y a su lado un frasquito con un líquido oscuro. «Anoche le di al viejo Jack una buena dosis», dijo la voz desde el techo, y se rió. En el funeral cantó una canción de taberna sobre la tumba. Luego se fue, prometiendo volver en siete años. Dicen que volvió, y que aún espera que alguien la llame por su nombre.",
                "Em 1820 encontraram John Bell agonizando, e ao lado um frasquinho de líquido escuro. \"Dei uma boa dose no velho Jack ontem à noite\", disse a voz do teto, e riu. No enterro ela cantou uma canção de taverna sobre a cova. Depois foi embora, prometendo voltar em sete anos. Dizem que voltou — e que ainda espera alguém chamá-la pelo nome." },
            ["e.Vodyanoy.name"] = new[] { "Vodyanoy", "Водяной", "Су иесі", "Vodianói", "Vodyanoy" },
            ["e.Vodyanoy.origin"] = new[] { "Slavic folklore", "Славянский фольклор", "Славян фольклоры", "Folclore eslavo", "Folclore eslavo" },
            ["e.Vodyanoy.lore"] = new[] {
                "The master of rivers and millponds: a fat old man with a frog's face, a beard of green weed, and webbed hands. He drags swimmers to the bottom to serve him in his underwater palace. Millers made bargains with him; everyone else carried iron: a knife or a nail in your pocket, and the vodyanoy will not grab you.",
                "Хозяин рек и мельничных омутов: толстый старик с лягушачьим лицом, бородой из зелёной тины и перепончатыми руками. Утаскивает купальщиков на дно — служить ему во дворце под водой. Мельники с ним договаривались, а все остальные носили железо: нож или гвоздь в кармане — и водяной тебя не схватит.",
                "Өзендер мен диірмен иірімдерінің иесі: бақа бетті, жасыл балдырдан сақалы бар, жарғақ қолды семіз шал. Суға шомылғандарды түбіне сүйреп, су астындағы сарайында қызмет еттіреді. Диірменшілер онымен келісетін, ал қалғандары темір алып жүретін: қалтаңда пышақ не шеге болса — су иесі сені ұстай алмайды.",
                "El amo de los ríos y los remansos del molino: un viejo gordo con cara de rana, barba de algas verdes y manos palmeadas. Arrastra a los bañistas al fondo para que le sirvan en su palacio bajo el agua. Los molineros pactaban con él; los demás llevaban hierro: un cuchillo o un clavo en el bolsillo, y el vodianói no te agarra.",
                "O senhor dos rios e dos remansos do moinho: um velho gordo de cara de sapo, barba de limo verde e mãos com membranas. Arrasta os banhistas para o fundo, para servi-lo no seu palácio debaixo d'água. Os moleiros faziam acordos com ele; os outros levavam ferro: uma faca ou um prego no bolso, e o vodyanoy não agarra você." },
            ["e.Vodyanoy.signs"] = new[] {
                "Bubbles rising, a deep croak. Stare at him too long and he sinks out of sight — and surfaces closer, somewhere else.",
                "Поднимаются пузыри, густое кваканье. Если долго на него смотреть, он уходит «под воду» — и всплывает ближе, в другом месте.",
                "Көпіршіктер көтеріледі, қою бақылдақ. Оған ұзақ қарасаң, «су астына» кетеді де, басқа жерде жақынырақ қалқып шығады.",
                "Burbujas que suben, un croar grave. Si lo miras demasiado se hunde, y emerge más cerca, en otro sitio.",
                "Bolhas subindo, um coaxar grave. Se você o encarar demais, ele afunda — e reaparece mais perto, em outro lugar." },
            ["e.Vodyanoy.defense"] = new[] {
                "Iron, up close. Let him come to you — with quick glances — and strike.",
                "Железо, вплотную. Дай ему подойти — бросая быстрые взгляды — и бей.",
                "Темір, таяп келгенде. Жылдам көз тастап, жақындасын — сосын ұр.",
                "Hierro, de cerca. Deja que se acerque, mirándolo solo a ratos, y golpea.",
                "Ferro, de perto. Deixe-o chegar — olhando só de relance — e golpeie." },
            ["e.Vodyanoy.hint"] = new[] {
                "It's a vodyanoy. He fears iron: glance at him, don't stare — let him come close and double-tap the screen.",
                "Это водяной. Он боится железа: бросай быстрые взгляды, не смотри в упор — подпусти вплотную и коснись экрана дважды.",
                "Бұл — су иесі. Ол темірден қорқады: тесіле қарамай, жылдам көз таста — таяп келгенде экранды екі рет түрт.",
                "Es un vodianói. Teme el hierro: míralo a ratos, sin fijar la vista; deja que se acerque y toca la pantalla dos veces.",
                "É um vodyanoy. Ele teme ferro: olhe de relance, sem encarar — deixe-o chegar perto e toque duas vezes na tela." },
            ["e.Vodyanoy.lair"] = new[] {
                "Where something shines like water: a mirror, a window, a glossy floor.",
                "Там, где что-то блестит, как вода: зеркало, окно, глянцевый пол.",
                "Бір нәрсе судай жылтырайтын жерде: айна, терезе, жылтыр еден.",
                "Donde algo brilla como el agua: un espejo, una ventana, un suelo brillante.",
                "Onde algo brilha como água: um espelho, uma janela, um chão brilhante." },
            ["e.Vodyanoy.tale"] = new[] {
                "A miller near Pskov kept the wheel turning for thirty years and never lost a man — every spring he drowned a black rooster in the millpond. The year his son laughed at the custom, the dam held, the wheel turned, and the son did not come home. They found only his boots on the bank, filled to the brim with green water.",
                "Мельник под Псковом тридцать лет крутил колесо и не потерял ни одного человека — каждую весну он топил в омуте чёрного петуха. В тот год, когда его сын посмеялся над обычаем, плотина выдержала, колесо крутилось, а сын не вернулся домой. На берегу нашли только его сапоги, полные до краёв зелёной воды.",
                "Псков маңындағы диірменші отыз жыл дөңгелегін айналдырып, бірде-бір адам жоғалтпады — әр көктемде иірімге қара әтеш батыратын. Ұлы бұл салтты мазақ еткен жылы бөгет шыдады, дөңгелек айналды, ал ұлы үйге оралмады. Жағадан тек оның етігін тапты, жиегіне дейін жасыл суға толы.",
                "Un molinero cerca de Pskov hizo girar la rueda treinta años sin perder a un solo hombre: cada primavera ahogaba un gallo negro en el remanso. El año en que su hijo se burló de la costumbre, la presa aguantó, la rueda giró, y el hijo no volvió a casa. En la orilla solo encontraron sus botas, llenas hasta el borde de agua verde.",
                "Um moleiro perto de Pskov girou a roda por trinta anos sem perder um homem — toda primavera afogava um galo preto no remanso. No ano em que o filho zombou do costume, a represa aguentou, a roda girou, e o filho não voltou para casa. Na margem só acharam as botas dele, cheias até a borda de água verde." },
            ["s.Ghost"] = new[] {
                "A pale figure at the edge of your eye. Gone.",
                "Бледная фигура на краю зрения. Исчезла.",
                "Көздің шетінде бозғылт кейіп. Жоқ болды.",
                "Una figura pálida en el borde de la vista. Ya no está.",
                "Uma figura pálida no canto do olho. Sumiu." },
            ["s.Shade"] = new[] {
                "Something tall stood in the corner of your eye — and stepped back into the dark.",
                "Что-то высокое стояло на краю зрения — и шагнуло обратно во тьму.",
                "Көздің шетінде бір биік нәрсе тұрды — сосын қараңғыға кері аттады.",
                "Algo alto estaba al borde de tu vista… y volvió a la oscuridad.",
                "Algo alto estava no canto do olho — e voltou para o escuro." },
            ["s.Albasty"] = new[] {
                "Quiet laughter, right behind your shoulder.",
                "Тихий смех — прямо за плечом.",
                "Ақырын күлкі — тура иығыңның артында.",
                "Una risa queda, justo detrás de tu hombro.",
                "Uma risada baixa, bem atrás do seu ombro." },
            ["s.Poltergeist"] = new[] {
                "Something flew off a shelf and smashed beside you.",
                "Что-то слетело с полки и разбилось рядом с тобой.",
                "Сөреден бір нәрсе ұшып түсіп, жаныңда сынды.",
                "Algo salió volando de una estantería y se rompió a tu lado.",
                "Algo voou de uma prateleira e se espatifou ao seu lado." },
            ["s.Double"] = new[] {
                "For a moment the screen showed a face. Yours — but smiling.",
                "На миг на экране проступило лицо. Твоё — но улыбается.",
                "Бір сәтке экранда бет көрінді. Сенікі — бірақ күлімдеп тұр.",
                "Por un instante la pantalla mostró una cara. La tuya… pero sonriendo.",
                "Por um instante a tela mostrou um rosto. O seu — mas sorrindo." },
            ["s.Kikimora"] = new[] {
                "Claws scraping across the ceiling, right above you.",
                "Когти скребут по потолку — прямо над тобой.",
                "Тырнақтар төбені тырнап жатыр — тура үстіңде.",
                "Garras raspando el techo, justo encima de ti.",
                "Garras raspando o teto, bem em cima de você." },
            ["s.Upyr"] = new[] {
                "Heavy steps behind you, closer and closer… then silence.",
                "Тяжёлые шаги за спиной, всё ближе… и тишина.",
                "Арқаңда ауыр қадамдар, жақындай береді… сосын тыныштық.",
                "Pasos pesados a tu espalda, cada vez más cerca… y silencio.",
                "Passos pesados atrás de você, cada vez mais perto… e silêncio." },
            ["s.Mara"] = new[] {
                "The light went out. When it came back, something was sitting much closer.",
                "Свет погас. Когда он вернулся, что-то сидело гораздо ближе.",
                "Жарық сөнді. Қайта жанғанда, бір нәрсе әлдеқайда жақын отыр еді.",
                "Se fue la luz. Cuando volvió, algo estaba sentado mucho más cerca.",
                "A luz apagou. Quando voltou, algo estava sentado bem mais perto." },
            ["s.Banshee"] = new[] {
                "A long wail rises somewhere {0} — and breaks off.",
                "Где-то {0} поднимается долгий вой — и обрывается.",
                "Бір жерде {0} ұзақ ұлу көтеріледі — сосын үзіледі.",
                "En algún lugar {0} se alza un largo lamento… y se corta.",
                "Em algum lugar {0} sobe um longo lamento — e se interrompe." },
            ["s.Domovoi"] = new[] {
                "Dishes rattle, something heavy stomps — and a pot flies past your head.",
                "Звякает посуда, что-то тяжело топает — и мимо головы пролетает горшок.",
                "Ыдыс сылдырлайды, бірдеңе ауыр тарсылдайды — басыңның жанынан құмыра ұшып өтеді.",
                "Tintinea la vajilla, algo pisotea con fuerza… y una olla pasa junto a tu cabeza.",
                "A louça tilinta, algo bate os pés pesado — e uma panela passa voando perto da sua cabeça." },
            ["s.Changeling"] = new[] {
                "A baby is crying right behind you. There is no baby in the house.",
                "Прямо за спиной плачет младенец. В доме нет младенца.",
                "Тура арқаңда нәресте жылап жатыр. Үйде нәресте жоқ.",
                "Un bebé llora justo detrás de ti. No hay ningún bebé en la casa.",
                "Um bebê chora bem atrás de você. Não há bebê nenhum na casa." },
            ["s.BlackDog"] = new[] {
                "Darkness. In it — two burning coals, low, at the height of a big dog.",
                "Темнота. В ней — два горящих угля, низко, на высоте большой собаки.",
                "Қараңғылық. Ішінде — екі жанған көмір, төменде, үлкен иттің бойындай биіктікте.",
                "Oscuridad. En ella, dos brasas encendidas, bajas, a la altura de un perro grande.",
                "Escuridão. Nela — duas brasas acesas, baixas, na altura de um cachorro grande." },
            ["s.Rusalka"] = new[] {
                "A wet palm slapped the glass from the inside — then another. Water runs down.",
                "Мокрая ладонь шлёпнула по стеклу изнутри — потом ещё одна. Стекает вода.",
                "Дымқыл алақан шыныны іштен шапалақтады — сосын тағы біреуі. Су ағып жатыр.",
                "Una palma mojada golpeó el cristal desde dentro, y luego otra. Escurre agua.",
                "Uma palma molhada bateu no vidro por dentro — depois outra. A água escorre." },
            ["s.Zheztyrnak"] = new[] {
                "Metal scraping on metal — right behind your back.",
                "Скрежет металла по металлу — прямо за спиной.",
                "Металдың металға қажалған шиқылы — тура арқаңда.",
                "Chirrido de metal contra metal, justo a tu espalda.",
                "Metal raspando em metal — bem atrás de você." },
            ["s.Llorona"] = new[] {
                "Sobbing right beside you — and wet palms pressed against the glass, as if someone begged to be let in.",
                "Рыдание совсем рядом — и к стеклу прижались мокрые ладони, будто кто-то просится внутрь.",
                "Жаныңда өксіп жылау — шыныға дымқыл алақандар басылды, біреу ішке кіргісі келгендей.",
                "Sollozos justo a tu lado, y unas palmas mojadas contra el cristal, como si alguien pidiera entrar.",
                "Soluços bem ao seu lado — e palmas molhadas coladas no vidro, como se alguém pedisse para entrar." },
            ["s.Ghoul"] = new[] {
                "Something crawls toward you in the dark, wet and chewing… then stops.",
                "Что-то ползёт к тебе в темноте, мокро чавкая… и замирает.",
                "Қараңғыда бір нәрсе сылп-сылп шайнап саған жорғалап келеді… сосын қатып қалады.",
                "Algo se arrastra hacia ti en la oscuridad, masticando… y se detiene.",
                "Algo rasteja até você no escuro, mastigando molhado… e para." },
            ["s.Kitsune"] = new[] {
                "A fox screamed right behind you, like a woman.",
                "Прямо за спиной закричала лиса — как женщина.",
                "Тура арқаңда түлкі айқайлады — әйелше.",
                "Una zorra gritó justo detrás de ti, como una mujer.",
                "Uma raposa gritou bem atrás de você, como uma mulher." },
            ["s.CorpoSeco"] = new[] {
                "Dry bones crunching in the dark, coming closer. Then nothing.",
                "Хруст сухих костей в темноте, всё ближе. Потом — ничего.",
                "Қараңғыда құрғақ сүйектердің сықыры, жақындай береді. Сосын — ештеңе.",
                "Crujido de huesos secos en la oscuridad, cada vez más cerca. Luego, nada.",
                "Ossos secos estalando no escuro, cada vez mais perto. Depois, nada." },
            ["s.MystanKempir"] = new[] {
                "{0}, an old woman is muttering. You can almost make out your name.",
                "Старушечье бормотание {0}. Кажется, звучит твоё имя.",
                "{0} кемпірдің күбірі. Сенің атың естілетін сияқты.",
                "El murmullo de una vieja {0}. Casi distingues tu nombre.",
                "O murmúrio de uma velha {0}. Quase dá para ouvir seu nome." },
            ["s.Jinn"] = new[] {
                "A hot wind swept over your head, full of voices.",
                "Над головой пронёсся горячий ветер, полный голосов.",
                "Басыңның үстінен дауыстарға толы ыстық жел соғып өтті.",
                "Un viento caliente, lleno de voces, pasó sobre tu cabeza.",
                "Um vento quente, cheio de vozes, passou sobre a sua cabeça." },
            ["s.Lechuza"] = new[] {
                "Wings beat right above your head, and a baby cries on the ceiling.",
                "Прямо над головой хлопают крылья, а с потолка плачет младенец.",
                "Тура басыңның үстінде қанат сарт-сұрт етеді, төбеден нәресте жылайды.",
                "Unas alas baten justo sobre tu cabeza, y un bebé llora en el techo.",
                "Asas batem bem em cima da sua cabeça, e um bebê chora no teto." },
            ["s.Pontianak"] = new[] {
                "A baby crying far, far away… and a small wet hand pressed against the glass. She is very close.",
                "Плач младенца — далеко-далеко… и к стеклу прижалась маленькая мокрая ладонь. Она совсем рядом.",
                "Нәрестенің жылауы — алыс-алыстан… шыныға кішкентай дымқыл алақан басылды. Ол дәл қасыңда.",
                "Un bebé llora muy, muy lejos… y una manita mojada se aprieta contra el cristal. Está muy cerca.",
                "Um bebê chora longe, bem longe… e uma mãozinha molhada cola no vidro. Ela está muito perto." },
            ["s.BabaYaga"] = new[] {
                "{0}, the thud of a mortar and the swish of a broom.",
                "{0} — стук ступы и шорох метлы.",
                "{0} — келінің дүңкілі мен сыпырғыштың сыбдыры.",
                "{0}, el golpe de un mortero y el roce de una escoba.",
                "{0}, a batida de um pilão e o roçar de uma vassoura." },
            ["s.Shurale"] = new[] {
                "Long fingers brushed the back of your neck. Laughter behind you.",
                "Длинные пальцы коснулись шеи. Смех за спиной.",
                "Ұзын саусақтар мойныңа тиді. Арқаңда күлкі.",
                "Unos dedos largos te rozaron la nuca. Risas a tu espalda.",
                "Dedos compridos roçaram sua nuca. Risadas atrás de você." },
            ["s.Cucuy"] = new[] {
                "The light died. Something under the floor breathed — and the light came back.",
                "Свет погас. Что-то внизу, у пола, вздохнуло — и свет вернулся.",
                "Жарық сөнді. Төменде, еденде бір нәрсе күрсінді — жарық қайта жанды.",
                "Se apagó la luz. Algo abajo, junto al suelo, respiró… y la luz volvió.",
                "A luz apagou. Algo lá embaixo, rente ao chão, respirou — e a luz voltou." },
            ["s.Kuchisake"] = new[] {
                "For a moment a woman's face filled the screen, mask pulled down: “Am I pretty?”",
                "На миг на весь экран — женское лицо, маска спущена: «Я красивая?»",
                "Бір сәтке бүкіл экранда — маскасы түскен әйел беті: «Мен сұлумын ба?»",
                "Por un instante, la cara de una mujer llenó la pantalla, con la mascarilla bajada: «¿Soy bonita?».",
                "Por um instante, um rosto de mulher encheu a tela, máscara abaixada: “Eu sou bonita?”" },
            ["s.BloodyMary"] = new[] {
                "For a moment the screen became a mirror — and she was standing behind you in it.",
                "На миг экран стал зеркалом — и в нём за твоей спиной стояла она.",
                "Бір сәтке экран айнаға айналды — онда сенің артыңда ол тұрды.",
                "Por un instante la pantalla se volvió un espejo… y en él, ella estaba detrás de ti.",
                "Por um instante a tela virou espelho — e nele ela estava atrás de você." },
            ["s.Ubyr"] = new[] {
                "A ball of fire hissed over your head and vanished into the dark.",
                "Над головой с шипением пролетел огненный шар и исчез во тьме.",
                "Басыңның үстінен от шар ысылдап ұшып өтіп, қараңғыға жоғалды.",
                "Una bola de fuego pasó siseando sobre tu cabeza y se perdió en la oscuridad.",
                "Uma bola de fogo passou chiando sobre a sua cabeça e sumiu no escuro." },
            ["s.Chupacabra"] = new[] {
                "Chittering, coming closer in jerks, from behind… then silence.",
                "Стрекот, рывками всё ближе, из-за спины… и тишина.",
                "Шықылдақ, жұлқынып жақындайды, арттан… сосын тыныштық.",
                "Chasquidos que se acercan a tirones, desde atrás… y silencio.",
                "Estalidos chegando aos trancos, por trás… e silêncio." },
            ["s.Jiangshi"] = new[] {
                "Thud. Thud. Thud — something is hopping toward you. Hold your breath.",
                "Бух. Бух. Бух — что-то прыгает к тебе. Задержи дыхание.",
                "Дүрс. Дүрс. Дүрс — бірдеңе саған секіріп келеді. Тынысыңды ұста.",
                "Pum. Pum. Pum: algo viene saltando hacia ti. Contén la respiración.",
                "Tum. Tum. Tum — algo vem pulando na sua direção. Prenda a respiração." },
            ["s.Strigoi"] = new[] {
                "The light went out, and wings beat in the dark right in front of you.",
                "Свет погас, и прямо перед тобой в темноте забились крылья.",
                "Жарық сөніп, дәл алдыңда қараңғыда қанаттар сабалады.",
                "Se apagó la luz y unas alas batieron en la oscuridad, justo delante de ti.",
                "A luz apagou, e asas bateram no escuro bem na sua frente." },
            ["s.Karakoncolos"] = new[] {
                "Darkness, icy air — and right in front of you someone calls your name. Don't answer.",
                "Темнота, ледяной воздух — и прямо перед тобой кто-то зовёт тебя по имени. Не отвечай.",
                "Қараңғылық, мұздай ауа — тура алдыңда біреу сені атыңнан шақырады. Жауап берме.",
                "Oscuridad, aire helado… y justo delante de ti alguien te llama por tu nombre. No respondas.",
                "Escuridão, ar gelado — e bem na sua frente alguém chama seu nome. Não responda." },
            ["s.Tunda"] = new[] {
                "A familiar woman at the edge of sight, humming. One of her legs is a stick.",
                "Знакомая женщина на краю зрения напевает. Одна нога у неё — палка.",
                "Көздің шетінде таныс әйел ыңылдап тұр. Бір аяғы — таяқ.",
                "Una mujer conocida al borde de la vista, tarareando. Una de sus piernas es un palo.",
                "Uma mulher conhecida no canto do olho, cantarolando. Uma das pernas é um pau." },
            ["s.Aswang"] = new[] {
                "“Tik-tik”… very quietly. Right behind you.",
                "«Тик-тик»… совсем тихо. Прямо за спиной.",
                "«Тік-тік»… мүлде ақырын. Тура арқаңда.",
                "«Tik-tik»… muy bajito. Justo detrás de ti.",
                "“Tik-tik”… bem baixinho. Bem atrás de você." },
            ["s.Vodyanoy"] = new[] {
                "A webbed, dripping hand pressed against the glass. Somewhere below, water gurgles.",
                "К стеклу прижалась перепончатая мокрая ладонь. Где-то внизу булькает вода.",
                "Шыныға жарғақты дымқыл алақан басылды. Төменде бір жерде су бұлқылдайды.",
                "Una mano palmeada y chorreante se apretó contra el cristal. Abajo borbotea el agua.",
                "Uma mão com membranas, pingando, colou no vidro. Lá embaixo a água borbulha." },
            ["s.Abaasy"] = new[] {
                "Heavy single-legged hops, closer and closer, and the grinding of iron teeth.",
                "Тяжёлые прыжки на одной ноге, всё ближе, и скрежет железных зубов.",
                "Бір аяқпен ауыр секірістер, жақындай береді, темір тістердің шиқылы.",
                "Brincos pesados sobre una sola pierna, cada vez más cerca, y el rechinar de dientes de hierro.",
                "Pulos pesados numa perna só, cada vez mais perto, e o ranger de dentes de ferro." },
            ["s.MulaSemCabeca"] = new[] {
                "Hooves galloping on stone, coming straight for you — and they stop.",
                "Копыта скачут по камню, прямо на тебя — и замолкают.",
                "Тұяқтар тасты дүсірлетіп, тура саған шабады — сосын тынады.",
                "Cascos galopando sobre piedra, directo hacia ti… y se detienen.",
                "Cascos galopando na pedra, direto para você — e param." },
            ["s.Penanggalan"] = new[] {
                "Something wet dripped on you from above. Don't look up.",
                "Сверху на тебя капнуло что-то мокрое. Не смотри наверх.",
                "Үстіңнен бір дымқыл нәрсе тамды. Жоғары қарама.",
                "Algo húmedo te goteó desde arriba. No mires hacia arriba.",
                "Algo molhado pingou em você lá de cima. Não olhe para cima." },
            ["s.BellWitch"] = new[] {
                "Something smashed against the wall. A slap rang out in the empty room — then an old woman began to sing.",
                "Что-то разбилось о стену. В пустой комнате раздалась пощёчина — потом запела старуха.",
                "Бір нәрсе қабырғаға соғылып сынды. Бос бөлмеде шапалақ естілді — сосын бір кемпір ән сала бастады.",
                "Algo se estrelló contra la pared. Sonó una bofetada en la habitación vacía; luego una anciana empezó a cantar.",
                "Algo se espatifou na parede. Um tapa estalou no quarto vazio — depois uma velha começou a cantar." },
            ["s.ZhalmauyzKempir"] = new[] {
                "{0}, seven voices whisper at once, arguing over who eats first.",
                "{0} шепчут семь голосов разом — спорят, кто будет есть первым.",
                "{0} жеті дауыс бірден сыбырлайды — кім бірінші жейтінін таласып жатыр.",
                "{0} susurran siete voces a la vez, discutiendo quién comerá primero.",
                "{0} sete vozes sussurram ao mesmo tempo, discutindo quem come primeiro." },
            ["night_log"] = new[] { "LOG", "ЗАПИСИ", "ЖАЗБАЛАР", "REGISTRO", "REGISTRO" },
            ["log_empty"] = new[] {
                "Nothing has happened yet. Everything the night tells you will be written here.",
                "Пока ничего не случилось. Всё, что скажет ночь, будет записано здесь.",
                "Әзірге ештеңе болған жоқ. Түннің айтқанының бәрі осында жазылады.",
                "Todavía no ha pasado nada. Todo lo que diga la noche quedará escrito aquí.",
                "Ainda não aconteceu nada. Tudo o que a noite disser ficará escrito aqui." },
            ["preview_tap"] = new[] { "Tap to go back", "Нажми, чтобы вернуться", "Қайту үшін бас", "Toca para volver", "Toque para voltar" },
            ["preview_no_camera"] = new[] {
                "The camera is not available — allow access to see the preview.",
                "Камера недоступна — разреши доступ, чтобы увидеть превью.",
                "Камера қолжетімсіз — алдын ала көру үшін рұқсат бер.",
                "La cámara no está disponible: permite el acceso para ver la vista previa.",
                "A câmera não está disponível — permita o acesso para ver a prévia." },
            ["menu_items"] = new[] {
                "HOW TO WARD THEM OFF · tap to practise",
                "ЧЕМ ПРОГОНЯТЬ · нажми, чтобы потренироваться",
                "НЕМЕН ҚУУ КЕРЕК · жаттығу үшін бас",
                "CÓMO AHUYENTARLOS · toca para practicar",
                "COMO AFASTÁ-LOS · toque para treinar" },
            ["g.Salt"] = new[] { "Swipe up", "Вверх", "Жоғары", "Arriba", "Para cima" },
            ["g.Lantern"] = new[] { "Hold", "Зажми", "Басып тұр", "Mantén", "Segure" },
            ["g.Iron"] = new[] { "Double tap", "Два касания", "Екі рет түрт", "Doble toque", "Toque duplo" },
            ["g.Bell"] = new[] { "Shake", "Встряхни", "Сілкіле", "Agita", "Chacoalhe" },
            ["g.Mirror"] = new[] { "Swipe down", "Вниз", "Төмен", "Abajo", "Para baixo" },
            ["g.Wormwood"] = new[] { "Zigzag", "Зигзаг", "Ирек", "Zigzag", "Zigue-zague" },
            ["too_far_look"] = new[] {
                "Too far. Look away — it only moves when you don't watch it. Then turn sharply and strike.",
                "Слишком далеко. Отвернись — она движется, только когда на неё не смотрят. Потом резко повернись и бей.",
                "Тым алыс. Теріс қара — оған қарамағанда ғана қозғалады. Сосын кенет бұрылып, ұр.",
                "Demasiado lejos. Aparta la vista: solo se mueve cuando no la miras. Luego gírate de golpe y golpea.",
                "Longe demais. Desvie o olhar — só se move quando você não olha. Depois vire de repente e golpeie." },
            ["h.IronNow"] = new[] {
                "Close enough! Double-tap the screen now.",
                "Близко! Коснись экрана дважды — сейчас.",
                "Жақын! Экранды қазір екі рет түрт.",
                "¡Lo bastante cerca! Toca la pantalla dos veces ya.",
                "Perto o bastante! Toque duas vezes na tela agora." },
            ["faint"] = new[] {
                "Everything went dark… You come round. It is still here.",
                "В глазах потемнело… Ты приходишь в себя. Оно всё ещё здесь.",
                "Көз алды қарауытты… Есіңді жиясың. Ол әлі осында.",
                "Todo se volvió negro… Vuelves en ti. Sigue aquí.",
                "Tudo escureceu… Você volta a si. Ainda está aqui." },
            ["h.StandStill"] = new[] {
                "While you scan the room, stay in one spot and just turn around. After that you can walk.",
                "Пока осматриваешь комнату, стой на месте и только поворачивайся. Потом можно ходить.",
                "Бөлмені қарап шыққанша бір орында тұрып, тек бұрыл. Содан кейін жүре бересің.",
                "Mientras examinas la habitación, quédate en un sitio y solo gira. Después podrás caminar.",
                "Enquanto examina o quarto, fique num só lugar e apenas gire. Depois você pode andar." },
            ["h.Invisible"] = new[] {
                "You can't see it — it's invisible. Turn toward the crashes and use what it fears.",
                "Его не видно — он невидим. Повернись туда, где грохочет, и примени то, чего он боится.",
                "Ол көрінбейді — ол көзге көрінбейтін. Тарсыл шыққан жаққа бұрыл да, оның неден қорқатынын қолдан.",
                "No se ve: es invisible. Gírate hacia los golpes y usa lo que teme.",
                "Não dá para ver — é invisível. Vire-se para onde vêm as batidas e use o que ele teme." },
            ["test_next"] = new[] { "TEST: NEXT NIGHT", "ТЕСТ: СЛЕДУЮЩЕЙ НОЧЬЮ", "ТЕСТ: КЕЛЕСІ ТҮНІ", "PRUEBA: PRÓXIMA NOCHE", "TESTE: PRÓXIMA NOITE" },
            ["test_next_set"] = new[] { "Next night: {0}", "Следующей ночью придёт: {0}", "Келесі түні келеді: {0}", "La próxima noche vendrá: {0}", "Na próxima noite virá: {0}" },
            ["n.Possession"] = new[] {
                "Their eyes went black for a moment. Something is looking out through them.",
                "На миг их глаза стали чёрными. Сквозь них смотрит что-то другое.",
                "Бір сәтке олардың көздері қап-қара болды. Солар арқылы басқа бірдеңе қарап тұр.",
                "Por un instante sus ojos se volvieron negros. Algo está mirando a través de ellos.",
                "Por um instante os olhos ficaram pretos. Algo está olhando através deles." },
            // ---------- улики ----------
            ["c.Frost.name"] = new[] { "Cold", "Холод", "Суық", "Frío", "Frio" },
            ["c.Frost.howto"] = new[] { "In the thermal camera the lair shows as a blue cold spot, below zero.", "В тепловизоре логово видно синим холодным пятном, ниже нуля.", "Тепловизорда ұя көк суық дақ болып көрінеді, нөлден төмен.", "En la cámara térmica la guarida aparece como una mancha fría azul, bajo cero.", "Na câmera térmica o covil aparece como uma mancha fria azul, abaixo de zero." },
            ["c.Whisper.name"] = new[] { "Whisper", "Шёпот", "Сыбыр", "Susurro", "Sussurro" },
            ["c.Whisper.howto"] = new[] { "A quiet whisper from one spot. With headphones you can tell where.", "Тихий шёпот из одной точки. В наушниках слышно, откуда.", "Бір нүктеден шыққан ақырын сыбыр. Құлаққаппен қайдан екені естіледі.", "Un susurro desde un punto. Con auriculares se oye de dónde.", "Um sussurro vindo de um ponto. Com fones dá para ouvir de onde." },
            ["c.Compass.name"] = new[] { "EMF 5", "ЭМП 5", "ЭМӨ 5", "EMF 5", "EMF 5" },
            ["c.Compass.howto"] = new[] { "The EMF reader hits 5 when aimed at the lair.", "ЭМП-детектор показывает 5, когда наведён на логово.", "ЭМӨ-детектор ұяға бағытталғанда 5 көрсетеді.", "El detector EMF marca 5 al apuntar a la guarida.", "O detector EMF marca 5 quando apontado para o covil." },
            ["c.Static.name"] = new[] { "Static", "Помехи", "Кедергі", "Interferencias", "Chiado" },
            ["c.Static.howto"] = new[] { "The picture tears with static when the camera points at the lair.", "Картинка рвётся помехами, когда камера направлена на логово.", "Камера ұяға бағытталғанда сурет кедергімен бұзылады.", "La imagen se rompe con interferencias al apuntar a la guarida.", "A imagem se rasga com chiado ao apontar para o covil." },
            ["c.Knock.name"] = new[] { "Knocking", "Стук", "Тықыл", "Golpes", "Batidas" },
            ["c.Knock.howto"] = new[] { "Three knocks from one place. Floor creaks are not a clue.", "Три удара из одного места. Скрипы пола — не улика.", "Бір жерден үш рет тықыл. Еденнің сықыры — дәлел емес.", "Tres golpes desde un sitio. Los crujidos del suelo no son pista.", "Três batidas de um lugar. Rangidos no chão não são pista." },
            ["c.Radio.name"] = new[] { "Radio", "Радио", "Радио", "Radio", "Rádio" },
            ["c.Radio.howto"] = new[] { "Turn on the spirit box and ask out loud: “Are you here?” — it answers in a distorted voice.", "Включи радио духов и спроси вслух: «Ты здесь?» — оно ответит искажённым голосом.", "Рухтар радиосын қосып, дауыстап сұра: «Сен мұндасың ба?» — ол бұрмаланған дауыспен жауап береді.", "Enciende la radio de espíritus y pregunta en voz alta: «¿Estás aquí?»: responde con voz distorsionada.", "Ligue o rádio dos espíritos e pergunte em voz alta: “Você está aí?” — ele responde com voz distorcida." },
            ["c.NightVision.name"] = new[] { "Silhouette", "Силуэт", "Сұлба", "Silueta", "Silhueta" },
            ["c.NightVision.howto"] = new[] { "Through the night camera a silhouette flashes in the lair for a moment.", "В ночной камере на миг виден силуэт в логове.", "Түнгі камерада ұяда бір сәтке сұлба көрінеді.", "Con la cámara nocturna se ve un instante una silueta en la guarida.", "Na câmera noturna uma silhueta aparece por um instante no covil." },
        };
    }
}
